INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0009-000000000001','00000001-0000-0000-0000-000000000009','00000000-0000-0000-0001-000000000001',1,'to-be-afirmativa','{"es":"To Be: Forma Afirmativa","en":"To Be: Affirmative Form"}','{"es":"Aprende las tres formas del verbo To Be en afirmativo: am, is, are — con contracciones y ejemplos reales.","en":"Learn the three affirmative forms of To Be: am, is, are — with contractions and real examples."}','theory_practice',25,20,'{"intro":"El verbo TO BE (ser/estar) es el más importante de toda la lengua inglesa. Sin él no puedes presentarte, describir personas, hablar de tu trabajo ni expresar cómo te sientes. En español usamos SER para la identidad y ESTAR para los estados, pero el inglés usa un solo verbo TO BE para ambos usos. Dominarlo es tu primera gran conquista en inglés.","sections":[{"type":"explanation","title":"LAS TRES FORMAS AFIRMATIVAS","text":"To Be tiene tres formas en el presente: AM, IS y ARE. La elección depende exclusivamente del sujeto. AM se usa SOLO con I (yo). IS se usa con he (él), she (ella) e it (cosas, animales, conceptos). ARE se usa con you (tú/usted/ustedes), we (nosotros) y they (ellos/ellas). Este patrón es absolutamente fijo — sin excepciones."},{"type":"table","title":"CONJUGACIÓN COMPLETA: FORMA LARGA","headers":["Pronombre","To Be","Equivalente español","Ejemplo"],"rows":[["I","am","soy / estoy","I am a student. (Soy estudiante.)"],["You","are","eres / estás","You are my friend. (Eres mi amigo.)"],["He","is","es / está","He is a doctor. (Él es médico.)"],["She","is","es / está","She is happy. (Ella está feliz.)"],["It","is","es / está","It is cold. (Está frío / Hace frío.)"],["We","are","somos / estamos","We are from Mexico. (Somos de México.)"],["You (pl.)","are","son / están","You are welcome. (De nada.)"],["They","are","son / están","They are teachers. (Son profesores.)"]]},{"type":"explanation","title":"LAS CONTRACCIONES — LA FORMA NATURAL","text":"En inglés hablado e informal SIEMPRE se usan las contracciones. Decir ''I am'' en lugar de ''I''m'' suena rígido y artificial. La contracción se forma uniendo el pronombre con el verbo y reemplazando la vocal con un apóstrofe: I am → I''m, You are → You''re, He is → He''s, She is → She''s, It is → It''s, We are → We''re, They are → They''re."},{"type":"table","title":"CONTRACCIONES DE TO BE","headers":["Forma larga","Contracción","Ejemplo","Traducción"],"rows":[["I am","I''m","I''m 25 years old.","Tengo 25 años."],["You are","You''re","You''re very tall.","Eres muy alto."],["He is","He''s","He''s my brother.","Es mi hermano."],["She is","She''s","She''s a lawyer.","Ella es abogada."],["It is","It''s","It''s a beautiful day.","Es un día hermoso."],["We are","We''re","We''re from Colombia.","Somos de Colombia."],["They are","They''re","They''re my parents.","Son mis padres."]]},{"type":"explanation","title":"SER O ESTAR: DOS VERBOS EN UNO","text":"To Be corresponde tanto al SER como al ESTAR español. Para IDENTIDAD usa To Be como SER: ''I am Carlos'' (Soy Carlos), ''She is Mexican'' (Ella es mexicana), ''He is a teacher'' (Él es profesor). Para ESTADOS usa To Be como ESTAR: ''I am tired'' (Estoy cansado), ''She is here'' (Ella está aquí), ''We are happy'' (Estamos felices). El contexto siempre aclara el significado."},{"type":"examples","title":"EJEMPLOS EN CONTEXTO REAL","items":[{"label":"Presentación","en":"Hi! I''m Ana. I''m 28 and I''m a nurse.","es":"¡Hola! Soy Ana. Tengo 28 años y soy enfermera."},{"label":"Descripción","en":"He''s my best friend. He''s funny and kind.","es":"Es mi mejor amigo. Es gracioso y amable."},{"label":"Origen y estado","en":"We''re from Argentina. We''re in Madrid now.","es":"Somos de Argentina. Estamos en Madrid ahora."},{"label":"Estado emocional","en":"She''s tired today. It''s Monday.","es":"Ella está cansada hoy. Es lunes."},{"label":"Descripción de objeto","en":"It''s a new phone. It''s very fast.","es":"Es un teléfono nuevo. Es muy rápido."}]},{"type":"note","variant":"warning","text":"CUIDADO con IT''S vs ITS: ''It''s'' (con apóstrofe) siempre significa ''it is''. ''Its'' (sin apóstrofe) es el posesivo de ''it'' (su). Ejemplo: ''It''s a cat. Its name is Luna.'' = ''Es un gato. Su nombre es Luna.''"},{"type":"note","variant":"tip","text":"En respuestas cortas no se puede contraer el verbo al final de la frase. Se dice ''Yes, I am'' (NO ''Yes, I''m'') y ''Yes, she is'' (NO ''Yes, she''s''). Las contracciones solo aparecen cuando hay algo después del verbo."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0009-000000000002','00000001-0000-0000-0000-000000000009','00000000-0000-0000-0001-000000000001',2,'to-be-negativa','{"es":"To Be: Forma Negativa","en":"To Be: Negative Form"}','{"es":"Aprende a negar con To Be usando am not, is not e are not, con sus contracciones isn''t y aren''t.","en":"Learn to negate with To Be using am not, is not, are not, with contractions isn''t and aren''t."}','theory_practice',25,20,'{"intro":"Para decir que algo NO es o NO está, simplemente añadimos NOT después del verbo To Be. Es una de las formas de negación más simples del inglés: no hay auxiliares extra, no hay ''no'' antes del verbo como en español. Solo To Be + NOT. En esta lección dominarás todas las formas negativas y sus contracciones.","sections":[{"type":"explanation","title":"LA REGLA BÁSICA: TO BE + NOT","text":"Para negar con To Be, añades NOT justo después del verbo: I am not (no soy/estoy), You are not (no eres/estás), He is not (no es/está), She is not (no es/está), It is not (no es/está), We are not (no somos/estamos), They are not (no son/están). Es directo y consistente — siempre la misma estructura."},{"type":"table","title":"FORMAS NEGATIVAS COMPLETAS","headers":["Forma larga","Contracción tipo 1","Contracción tipo 2","Ejemplo"],"rows":[["I am not","I''m not","(solo esta)","I''m not a student."],["You are not","You''re not","You aren''t","You aren''t from here."],["He is not","He''s not","He isn''t","He isn''t my brother."],["She is not","She''s not","She isn''t","She isn''t a doctor."],["It is not","It''s not","It isn''t","It isn''t cold today."],["We are not","We''re not","We aren''t","We aren''t tired."],["They are not","They''re not","They aren''t","They aren''t here."]]},{"type":"explanation","title":"DOS CONTRACCIONES POSIBLES","text":"Para la mayoría de pronombres hay DOS formas contraídas posibles. Con ''you are not'' puedes decir ''you''re not'' o ''you aren''t'' — ambas son correctas. La excepción es ''I am not'' que solo tiene una contracción: ''I''m not''. NUNCA se dice ''I amn''t'' en inglés moderno. Recuerda: ''isn''t'' = is not, ''aren''t'' = are not."},{"type":"explanation","title":"USOS DE LA NEGACIÓN CON TO BE","text":"La forma negativa de To Be sirve para corregir información falsa, expresar que algo no corresponde a una descripción, negar identidades o estados. Por ejemplo: ''She''s not a nurse — she''s a doctor'' (No es enfermera, es médica). ''I''m not tired, I''m hungry'' (No estoy cansado, tengo hambre). ''It isn''t Monday, it''s Tuesday'' (No es lunes, es martes)."},{"type":"examples","title":"EJEMPLOS EN CONTEXTO","items":[{"label":"Corrección","en":"He isn''t Spanish. He''s Italian.","es":"Él no es español. Es italiano."},{"label":"Negación de estado","en":"I''m not happy today. I''m a bit sad.","es":"No estoy feliz hoy. Estoy un poco triste."},{"label":"Negación de identidad","en":"We aren''t tourists. We''re residents.","es":"No somos turistas. Somos residentes."},{"label":"Negación de descripción","en":"The coffee isn''t hot. It''s cold.","es":"El café no está caliente. Está frío."},{"label":"Corrección de edad","en":"I''m not 30. I''m 28.","es":"No tengo 30 años. Tengo 28."}]},{"type":"note","variant":"tip","text":"En inglés coloquial, ''isn''t'' y ''aren''t'' son las formas preferidas en lugar de ''is not'' y ''are not''. ''Is not'' y ''are not'' se usan cuando quieres enfatizar la negación: ''She is NOT my girlfriend'' (enfático). En conversación normal: ''She isn''t my girlfriend''."},{"type":"note","variant":"warning","text":"Nunca digas ''I amn''t'' — no existe en inglés moderno. La única forma correcta es ''I''m not''. También evita ''I aren''t'' (incorrecto). Solo ''I''m not'' funciona para la primera persona singular."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0009-000000000003','00000001-0000-0000-0000-000000000009','00000000-0000-0000-0001-000000000001',3,'to-be-interrogativa','{"es":"To Be: Forma Interrogativa","en":"To Be: Question Form"}','{"es":"Aprende a hacer preguntas con To Be: preguntas de sí/no, respuestas cortas y preguntas con Wh-.","en":"Learn to ask questions with To Be: yes/no questions, short answers, and Wh- questions."}','theory_practice',25,20,'{"intro":"En inglés, hacer preguntas con To Be es muy fácil: solo inviertes el orden del sujeto y el verbo. No necesitas ningún auxiliar extra como en otras formas verbales. Esta inversión simple te permite hacer preguntas de sí/no y también preguntas con palabras interrogativas como What, Where, Who, How.","sections":[{"type":"explanation","title":"PREGUNTAS DE SÍ/NO: INVERSIÓN SUJETO-VERBO","text":"Para hacer una pregunta de sí/no con To Be, simplemente mueves el verbo (am/is/are) al principio de la oración, antes del sujeto: ''She is happy'' → ''Is she happy?'' — ''You are a student'' → ''Are you a student?'' — ''It is cold'' → ''Is it cold?'' — ''They are from Spain'' → ''Are they from Spain?'' El signo de interrogación va siempre al final."},{"type":"table","title":"ESTRUCTURA DE PREGUNTAS SÍ/NO","headers":["Afirmativa","Pregunta","Respuesta sí","Respuesta no"],"rows":[["I am a student.","Am I a student?","Yes, you are.","No, you aren''t."],["You are ready.","Are you ready?","Yes, I am.","No, I''m not."],["He is a teacher.","Is he a teacher?","Yes, he is.","No, he isn''t."],["She is from Brazil.","Is she from Brazil?","Yes, she is.","No, she isn''t."],["It is expensive.","Is it expensive?","Yes, it is.","No, it isn''t."],["We are late.","Are we late?","Yes, we are.","No, we aren''t."],["They are happy.","Are they happy?","Yes, they are.","No, they aren''t."]]},{"type":"explanation","title":"RESPUESTAS CORTAS — CÓMO RESPONDER CORRECTAMENTE","text":"En inglés NO se responde solo ''Yes'' o ''No'' — eso suena brusco. La forma correcta es usar una respuesta corta: ''Yes, I am'' / ''No, I''m not'' / ''Yes, she is'' / ''No, he isn''t''. La estructura es: Yes/No + pronombre sujeto + To Be (+ not para negativo). IMPORTANTE: En las respuestas cortas afirmativas NUNCA se usa contracción al final: ''Yes, she is'' (correcto), NO ''Yes, she''s'' (incorrecto)."},{"type":"explanation","title":"PREGUNTAS CON WH- (QUIÉN, QUÉ, DÓNDE, CÓMO)","text":"Para preguntas con palabras interrogativas (What = qué, Where = dónde, Who = quién, How = cómo, Why = por qué, Which = cuál, When = cuándo), la estructura es: Palabra interrogativa + To Be + Sujeto? Ejemplos: ''What is your name?'' (¿Cuál es tu nombre?), ''Where are you from?'' (¿De dónde eres?), ''How old are you?'' (¿Cuántos años tienes? — literalmente ''¿Qué tan viejo eres?''), ''Who is she?'' (¿Quién es ella?), ''Why are you sad?'' (¿Por qué estás triste?)."},{"type":"table","title":"PREGUNTAS WH- MÁS COMUNES","headers":["Pregunta en inglés","Traducción al español","Respuesta típica"],"rows":[["What is your name?","¿Cuál es tu nombre?","My name is Carlos."],["Where are you from?","¿De dónde eres?","I''m from Mexico."],["How old are you?","¿Cuántos años tienes?","I''m 25 years old."],["What is your job?","¿Cuál es tu trabajo?","I''m a teacher."],["Where is the hotel?","¿Dónde está el hotel?","It''s on Main Street."],["Who is that man?","¿Quién es ese hombre?","He''s my father."],["Why are you late?","¿Por qué llegas tarde?","I''m sorry, the bus was slow."]]},{"type":"examples","title":"DIÁLOGOS COMPLETOS","items":[{"label":"Conocer a alguien","en":"Are you from Spain? — No, I''m not. I''m from Argentina.","es":"¿Eres de España? — No, no lo soy. Soy de Argentina."},{"label":"En recepción","en":"Is the room ready? — Yes, it is. Here''s your key.","es":"¿Está lista la habitación? — Sí, lo está. Aquí está su llave."},{"label":"Preguntar por alguien","en":"Where is Dr. Smith? — She''s in her office.","es":"¿Dónde está la Dra. Smith? — Está en su oficina."},{"label":"Verificar información","en":"Are you Maria Garcia? — Yes, I am.","es":"¿Es usted María García? — Sí, lo soy."}]},{"type":"note","variant":"tip","text":"''How old are you?'' es la pregunta más común para preguntar la edad. En español decimos ''¿Cuántos años TIENES?'' pero en inglés se dice ''How old ARE you?'' (literalmente ''¿Qué tan viejo ERES?''). La respuesta también usa To Be: ''I''m 25'' o ''I''m 25 years old''."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0009-000000000004','00000001-0000-0000-0000-000000000009','00000000-0000-0000-0001-000000000001',4,'to-be-identidad-profesiones','{"es":"To Be: Identidad y Profesiones","en":"To Be: Identity and Professions"}','{"es":"Usa To Be para presentarte, decir tu nacionalidad, origen y profesión en inglés.","en":"Use To Be to introduce yourself, state your nationality, origin, and profession in English."}','theory_practice',25,20,'{"intro":"Una de las aplicaciones más inmediatas del verbo To Be es hablar sobre identidad: quién eres, de dónde vienes, qué haces. En esta lección aprenderás a presentarte completamente en inglés: tu nombre, tu nacionalidad, tu ciudad, tu profesión. Estas son las frases que usarás en el primer minuto de cualquier conversación en inglés.","sections":[{"type":"explanation","title":"PRESENTARSE: I AM + INFORMACIÓN","text":"Para presentarte en inglés usas I am (o I''m en forma informal) seguido de tu información personal. El orden típico en inglés es: nombre → edad → origen → profesión. ''Hi, I''m Carlos. I''m 30 years old. I''m from Guadalajara, Mexico. I''m an engineer.'' Nota que las profesiones en inglés NO llevan artículo cuando siguen a To Be + soy/eres/es: ''I am a doctor'' (SÍ artículo indefinido), ''She is the director'' (SÍ artículo definido cuando es único)."},{"type":"table","title":"VOCABULARIO DE PROFESIONES COMUNES","headers":["Inglés","Español","Ejemplo con To Be"],"rows":[["doctor / physician","médico/a","He''s a doctor at City Hospital."],["nurse","enfermero/a","She''s a nurse in the ICU."],["teacher","maestro/a, profesor/a","I''m an English teacher."],["engineer","ingeniero/a","They''re software engineers."],["lawyer","abogado/a","She''s a criminal lawyer."],["student","estudiante","We''re university students."],["manager","gerente","He''s the marketing manager."],["chef","chef, cocinero/a","She''s a chef at a French restaurant."],["programmer","programador/a","I''m a web programmer."],["architect","arquitecto/a","They''re architects from Barcelona."]]},{"type":"explanation","title":"NACIONALIDADES Y ORÍGENES","text":"Para decir tu nacionalidad usas: I am + adjetivo de nacionalidad. Los adjetivos de nacionalidad en inglés siempre se escriben con MAYÚSCULA. Ejemplos: Mexican (mexicano/a), Colombian (colombiano/a), Argentinian/Argentine (argentino/a), Spanish (español/a), American (estadounidense), Brazilian (brasileño/a), French (francés/francesa), German (alemán/alemana). Para el origen geográfico: ''I am from'' + ciudad/país: ''I''m from Buenos Aires'', ''She''s from Japan''."},{"type":"table","title":"NACIONALIDADES MÁS COMUNES","headers":["País","Nacionalidad","Ejemplo"],"rows":[["Mexico","Mexican","I''m Mexican. / I''m from Mexico."],["Colombia","Colombian","He''s Colombian."],["Argentina","Argentinian","She''s Argentinian."],["Spain","Spanish","They''re Spanish."],["USA","American","He''s American."],["Brazil","Brazilian","She''s Brazilian."],["France","French","He''s French."],["Germany","German","She''s German."],["Japan","Japanese","He''s Japanese."],["China","Chinese","She''s Chinese."]]},{"type":"examples","title":"PRESENTACIONES COMPLETAS","items":[{"label":"Presentación formal","en":"Good morning. My name is Dr. Rodriguez. I''m a cardiologist and I''m the head of the cardiology department.","es":"Buenos días. Me llamo Dr. Rodríguez. Soy cardiólogo y soy el jefe del departamento de cardiología."},{"label":"Presentación casual","en":"Hey! I''m Sofia. I''m 24, I''m from Bogotá, and I''m a graphic designer.","es":"¡Hola! Soy Sofía. Tengo 24 años, soy de Bogotá y soy diseñadora gráfica."},{"label":"Presentar a otros","en":"This is my colleague Ana. She''s a project manager and she''s from Madrid.","es":"Esta es mi colega Ana. Es gerente de proyectos y es de Madrid."},{"label":"Información laboral","en":"We''re a team of five engineers. Our boss is from San Francisco.","es":"Somos un equipo de cinco ingenieros. Nuestro jefe es de San Francisco."}]},{"type":"note","variant":"tip","text":"A vs AN con profesiones: Usa ''a'' antes de consonante (a doctor, a teacher, a nurse) y ''an'' antes de vocal (an engineer, an architect, an artist, an actor). El artículo depende del SONIDO, no de la letra escrita: ''a university'' (suena ''you-ni-ver-si-ty'' = consonante), ''an hour'' (la H es silenciosa, suena ''our'' = vocal)."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0009-000000000005','00000001-0000-0000-0000-000000000009','00000000-0000-0000-0001-000000000001',5,'to-be-estados-descripciones','{"es":"To Be: Estados y Descripciones","en":"To Be: States and Descriptions"}','{"es":"Usa To Be para describir cómo te sientes, cómo son las personas y cómo están las cosas.","en":"Use To Be to describe how you feel, what people are like, and what things are like."}','theory_practice',25,20,'{"intro":"Además de la identidad, To Be es esencial para expresar ESTADOS (cómo estás en este momento) y DESCRIPCIONES (cómo es alguien o algo). En esta lección aprenderás los adjetivos más útiles en inglés y cómo combinarlos con To Be para comunicarte de manera fluida y natural.","sections":[{"type":"explanation","title":"TO BE + ADJETIVO: LA FÓRMULA UNIVERSAL","text":"En inglés los adjetivos SIEMPRE van después de To Be cuando describen el sujeto: Sujeto + To Be + Adjetivo. ''The car is red'' (El coche es rojo), ''She is beautiful'' (Ella es hermosa), ''I am tired'' (Estoy cansado), ''The food is delicious'' (La comida está deliciosa). A diferencia del español, en inglés los adjetivos NO cambian de género ni número: ''He is tall'' / ''She is tall'' / ''They are tall'' — siempre la misma forma."},{"type":"table","title":"ADJETIVOS DE ESTADOS EMOCIONALES","headers":["Inglés","Español","Ejemplo"],"rows":[["happy","feliz, contento/a","I''m so happy today!"],["sad","triste","She''s sad because of the news."],["tired","cansado/a","We''re tired after the gym."],["excited","emocionado/a","They''re excited about the trip."],["bored","aburrido/a","He''s bored at home."],["angry","enojado/a","She''s angry with her brother."],["nervous","nervioso/a","I''m nervous about the exam."],["scared","asustado/a","The child is scared of the dark."],["surprised","sorprendido/a","We''re surprised by the news."],["confused","confundido/a","I''m confused by this exercise."]]},{"type":"table","title":"ADJETIVOS DE DESCRIPCIÓN FÍSICA","headers":["Inglés","Español","Ejemplo"],"rows":[["tall","alto/a","He''s very tall — over 1.90m."],["short","bajo/a","She''s short but very strong."],["young","joven","They''re young — both under 25."],["old","viejo/a, mayor","My grandmother is old but healthy."],["big / large","grande","The apartment is big."],["small / little","pequeño/a","It''s a small but cozy room."],["hot","caliente, caluroso","The coffee is hot. / It''s hot today."],["cold","frío/a, fresco","The water is cold. / I''m cold."],["new","nuevo/a","Her phone is new."],["old","viejo/a (objeto)","This laptop is old."]]},{"type":"explanation","title":"ADJETIVOS ANTES DEL SUSTANTIVO","text":"Los adjetivos en inglés también pueden ir ANTES del sustantivo (no solo después de To Be). ''A tall man'' (un hombre alto), ''a beautiful city'' (una ciudad hermosa), ''a cold drink'' (una bebida fría). En este caso NO se usa To Be. La posición del adjetivo cambia el significado ligeramente: ''The man is tall'' (El hombre es alto — describiendo al hombre) vs ''a tall man'' (un hombre alto — como característica dentro de una frase nominal)."},{"type":"examples","title":"DESCRIPCIONES EN CONTEXTO REAL","items":[{"label":"Describir persona","en":"My sister is very tall and slim. She''s also quite funny.","es":"Mi hermana es muy alta y delgada. También es bastante graciosa."},{"label":"Describir lugar","en":"The city is beautiful but it''s crowded and expensive.","es":"La ciudad es hermosa pero está llena de gente y es cara."},{"label":"Estado actual","en":"I''m exhausted. The meeting was long and I''m hungry too.","es":"Estoy agotado. La reunión fue larga y también tengo hambre."},{"label":"Describir objeto","en":"The new phone is amazing — it''s fast, light, and very thin.","es":"El teléfono nuevo es increíble — es rápido, ligero y muy delgado."},{"label":"Clima","en":"It''s sunny today but it''s cold. The wind is strong.","es":"Hoy hace sol pero hace frío. El viento es fuerte."}]},{"type":"note","variant":"tip","text":"Para intensificar un adjetivo en inglés usa: very (muy), quite (bastante), really (realmente), so (tan). ''She''s very smart'', ''He''s quite tall'', ''I''m really tired'', ''You''re so kind''. Para reducir la intensidad: a bit / a little (un poco): ''I''m a bit nervous'', ''It''s a little cold''."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0009-000000000006','00000001-0000-0000-0000-000000000009','00000000-0000-0000-0001-000000000001',6,'to-be-vs-tener','{"es":"To Be vs Tener en Español","en":"To Be vs Tener in Spanish"}','{"es":"Entiende por qué en inglés se dice ''I am hungry'' y no ''I have hunger'': expresiones con To Be que se traducen con Tener en español.","en":"Understand why in English you say ''I am hungry'' not ''I have hunger'': To Be expressions that translate as Tener in Spanish."}','theory_practice',25,20,'{"intro":"Uno de los errores más comunes de los hispanohablantes al aprender inglés es traducir directamente el verbo TENER cuando expresamos sensaciones físicas y emocionales. En español decimos ''Tengo hambre'', ''Tengo frío'', ''Tengo miedo'' usando el verbo TENER. En inglés estas mismas ideas se expresan con TO BE: ''I am hungry'', ''I am cold'', ''I am afraid''. Este error tan frecuente tiene solución fácil: memorizar la lista de expresiones en esta lección.","sections":[{"type":"explanation","title":"EL PROBLEMA: TENER EN ESPAÑOL = TO BE EN INGLÉS","text":"En español, muchas sensaciones físicas se construyen con TENER + sustantivo: tener hambre, tener sed, tener frío, tener calor, tener sueño, tener miedo, tener prisa, tener razón. En inglés estas mismas sensaciones se construyen con TO BE + adjetivo: to be hungry (tener hambre), to be thirsty (tener sed), to be cold (tener frío), to be hot (tener calor), to be sleepy (tener sueño), to be afraid (tener miedo), to be in a hurry (tener prisa), to be right (tener razón). El error clásico: ''I have hungry'' (INCORRECTO) → ''I am hungry'' (CORRECTO)."},{"type":"table","title":"EXPRESIONES TENER → TO BE","headers":["Español (TENER)","Inglés (TO BE)","Ejemplo completo","Traducción"],"rows":[["tener hambre","to be hungry","I''m hungry. Let''s eat!","Tengo hambre. ¡Comamos!"],["tener sed","to be thirsty","Are you thirsty? There''s water here.","¿Tienes sed? Hay agua aquí."],["tener frío","to be cold","She''s cold. She needs a coat.","Tiene frío. Necesita un abrigo."],["tener calor","to be hot","It''s hot today. We''re all hot.","Hace calor hoy. Todos tenemos calor."],["tener sueño","to be sleepy / tired","I''m so sleepy. I need coffee.","Tengo tanto sueño. Necesito café."],["tener miedo","to be afraid / scared","He''s afraid of spiders.","Tiene miedo de las arañas."],["tener prisa","to be in a hurry","I''m in a hurry! The bus is here!","¡Tengo prisa! ¡El autobús está aquí!"],["tener razón","to be right","You''re right. That''s the answer.","Tienes razón. Esa es la respuesta."],["tener suerte","to be lucky","We''re lucky! We got the last table.","¡Tenemos suerte! Conseguimos la última mesa."],["tener años","to be ... years old","I''m 30 years old.","Tengo 30 años."],["tener cuidado","to be careful","Be careful! The floor is wet.","¡Ten cuidado! El suelo está mojado."],["tener éxito","to be successful","She''s very successful in business.","Ella es muy exitosa en los negocios."]]},{"type":"explanation","title":"LA EDAD: OTRO CASO DE TENER → TO BE","text":"La edad en español se expresa con TENER: ''Tengo 25 años''. En inglés se usa TO BE: ''I am 25 years old'' o simplemente ''I''m 25''. La palabra ''years old'' es opcional pero muy común. Preguntar la edad: ''How old are you?'' (¿Cuántos años tienes?). Responder: ''I''m 25'' / ''I''m 25 years old'' / ''I am 25''. NUNCA: ''I have 25 years'' (incorrecto)."},{"type":"explanation","title":"EL TIEMPO ATMOSFÉRICO: IT''S","text":"En español el tiempo se expresa de varias formas: ''hace frío'', ''hay niebla'', ''está nublado''. En inglés casi siempre usamos IT IS (It''s) + adjetivo: It''s cold (hace frío / está frío), It''s hot (hace calor), It''s sunny (hace sol / está soleado), It''s cloudy (está nublado), It''s windy (hace viento), It''s foggy (hay niebla / está brumoso), It''s rainy (está lluvioso). El sujeto IT no tiene un referente claro — es solo el sujeto gramatical obligatorio en inglés."},{"type":"examples","title":"SITUACIONES REALES","items":[{"label":"Restaurante","en":"Are you hungry? — Yes, I''m starving! I''m also very thirsty.","es":"¿Tienes hambre? — ¡Sí, me muero de hambre! También tengo mucha sed."},{"label":"Clima","en":"It''s freezing outside! Aren''t you cold without a jacket?","es":"¡Hace un frío helador afuera! ¿No tienes frío sin chaqueta?"},{"label":"Urgencia","en":"I''m in a hurry! I''m late for my meeting.","es":"¡Tengo prisa! Llego tarde a mi reunión."},{"label":"Acordar algo","en":"She''s right, you know. The meeting is at 3, not 4.","es":"Ella tiene razón, sabes. La reunión es a las 3, no a las 4."},{"label":"Edad","en":"How old is your son? — He''s 7 years old.","es":"¿Cuántos años tiene tu hijo? — Tiene 7 años."}]},{"type":"note","variant":"warning","text":"Los errores más frecuentes: ''I have hungry'' ❌ → ''I''m hungry'' ✅ | ''I have 30 years'' ❌ → ''I''m 30 years old'' ✅ | ''I have cold'' ❌ → ''I''m cold'' ✅ | ''I have fear'' ❌ → ''I''m afraid'' ✅. Memoriza la regla: sensaciones físicas = TO BE + adjetivo en inglés."}]}','true');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0001-000000000001','00000002-0000-0000-0009-000000000001',1,'flashcard','{"text":"I am a student","subtext":"¿Cuál es la contracción natural?"}','{"text":"I''m a student","phonetic":"/aɪm ə ˈstjuːdənt/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0002-000000000001','00000002-0000-0000-0009-000000000001',2,'flashcard','{"text":"They are my parents","subtext":"¿Cuál es la contracción?"}','{"text":"They''re my parents","phonetic":"/ðeər maɪ ˈpeərənts/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0003-000000000001','00000002-0000-0000-0009-000000000001',3,'multiple_choice','{"text":"¿Cuál es la forma correcta? ''Ella ___ doctora.''"}','{"text":"She is a doctor."}','["She am a doctor.","She are a doctor.","Her is a doctor."]','{"es":"Con los pronombres he, she, it siempre se usa IS. She is = ella es/está. AM solo se usa con I, ARE con you/we/they."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0004-000000000001','00000002-0000-0000-0009-000000000001',4,'multiple_choice','{"text":"Completa: ''We ___ from Colombia. We ___ very happy here.''"}','{"text":"are / are"}','["is / is","am / am","are / is"]','{"es":"Con el pronombre WE siempre usamos ARE. Tanto para el origen (somos de Colombia) como para el estado (estamos muy felices). ARE no cambia con WE en ningún contexto."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0005-000000000001','00000002-0000-0000-0009-000000000001',5,'multiple_choice','{"text":"¿Cuál oración es correcta?"}','{"text":"It''s a beautiful city. It''s very old."}','["It''s a beautiful city. Its very old.","Its a beautiful city. It''s very old.","Its a beautiful city. Its very old."]','{"es":"IT''S (con apóstrofe) = it is. ITS (sin apóstrofe) = su/de ello (posesivo). ''It''s a beautiful city'' = ''Es una ciudad hermosa''. ''Its name is Rome'' = ''Su nombre es Roma''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0006-000000000001','00000002-0000-0000-0009-000000000001',6,'fill_blank','{"text":"Hi, my name is Pedro. I ___ 22 years old and I ___ an engineer."}','{"text":"am / am","accepted":["am / am"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0007-000000000001','00000002-0000-0000-0009-000000000001',7,'translation','{"text":"Somos de España. Somos profesores de inglés."}','{"text":"We are from Spain. We are English teachers.","accepted":["We are from Spain. We are English teachers.","We''re from Spain. We''re English teachers.","We are from Spain. We''re English teachers."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0001-0008-000000000001','00000002-0000-0000-0009-000000000001',8,'translation','{"text":"Ella es mi mejor amiga. Es muy inteligente y muy amable."}','{"text":"She is my best friend. She is very intelligent and very kind.","accepted":["She is my best friend. She is very intelligent and very kind.","She''s my best friend. She''s very intelligent and very kind.","She''s my best friend. She is very intelligent and kind."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0001-000000000001','00000002-0000-0000-0009-000000000002',1,'flashcard','{"text":"He is not Spanish","subtext":"Escribe las dos contracciones posibles"}','{"text":"He''s not Spanish / He isn''t Spanish","phonetic":"/hiːz nɒt / hiː ˈɪznt/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0002-000000000001','00000002-0000-0000-0009-000000000002',2,'multiple_choice','{"text":"¿Cuál es la forma CORRECTA para negar con ''I''?"}','{"text":"I''m not tired."}','["I amn''t tired.","I aren''t tired.","I isn''t tired."]','{"es":"Para I am not, la ÚNICA contracción correcta es ''I''m not''. ''Amn''t'' no existe en inglés moderno. ''Aren''t'' y ''isn''t'' son incorrectas con ''I''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0003-000000000001','00000002-0000-0000-0009-000000000002',3,'multiple_choice','{"text":"''They ___ from France. They''re from Italy.''"}','{"text":"aren''t"}','["isn''t","am not","isn''t not"]','{"es":"Con THEY usamos ARE, por lo tanto la negación contraída es AREN''T (are not). IS se usa con he/she/it → isn''t. AM se usa con I → am not."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0004-000000000001','00000002-0000-0000-0009-000000000002',4,'multiple_choice','{"text":"¿Cuándo usas ''is not'' en lugar de ''isn''t''?"}','{"text":"Cuando quieres enfatizar la negación: ''She is NOT my girlfriend.''"}','["Cuando el sujeto es femenino","Nunca, siempre se usa ''isn''t''","Solo en preguntas"]','{"es":"La forma larga ''is not'' / ''are not'' se usa para enfatizar la negación. ''She isn''t here'' (información) vs ''She is NOT my girlfriend'' (énfasis/corrección fuerte)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0005-000000000001','00000002-0000-0000-0009-000000000002',5,'fill_blank','{"text":"This phone ___ new. It''s quite old actually. And it ___ very fast."}','{"text":"isn''t / isn''t","accepted":["isn''t / isn''t","is not / is not"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0006-000000000001','00000002-0000-0000-0009-000000000002',6,'fill_blank','{"text":"We ___ tourists. We live here. This is our city."}','{"text":"aren''t","accepted":["aren''t","are not"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0007-000000000001','00000002-0000-0000-0009-000000000002',7,'translation','{"text":"No soy médico. Soy estudiante de medicina."}','{"text":"I''m not a doctor. I''m a medical student.","accepted":["I''m not a doctor. I''m a medical student.","I am not a doctor. I am a medical student.","I''m not a doctor. I am a medical student."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0002-0008-000000000001','00000002-0000-0000-0009-000000000002',8,'translation','{"text":"El hotel no está cerca. No está en el centro de la ciudad."}','{"text":"The hotel isn''t close. It isn''t in the city center.","accepted":["The hotel isn''t close. It isn''t in the city center.","The hotel is not close. It is not in the city center.","The hotel isn''t nearby. It''s not in the city center."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0001-000000000001','00000002-0000-0000-0009-000000000003',1,'flashcard','{"text":"Where are you from?","subtext":"Pregunta fundamental — memorízala"}','{"text":"¿De dónde eres? / ¿De dónde es usted?","phonetic":"/wɛr ɑːr juː frɒm/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0002-000000000001','00000002-0000-0000-0009-000000000003',2,'flashcard','{"text":"How old are you?","subtext":"Pregunta sobre la edad — literalmente ''¿Qué tan viejo eres?''"}','{"text":"¿Cuántos años tienes?","phonetic":"/haʊ oʊld ɑːr juː/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0003-000000000001','00000002-0000-0000-0009-000000000003',3,'multiple_choice','{"text":"Para hacer una pregunta de sí/no con To Be, ¿qué haces?"}','{"text":"Mueves el verbo (am/is/are) al principio, antes del sujeto."}','["Añades ''do'' al principio de la oración","Añades ''?'' al final sin cambiar el orden","Añades ''not'' después del verbo"]','{"es":"En inglés, las preguntas con To Be se forman invirtiendo sujeto y verbo: ''She is happy'' → ''Is she happy?''. No necesitas ningún auxiliar extra. Esta inversión es la clave."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0004-000000000001','00000002-0000-0000-0009-000000000003',4,'multiple_choice','{"text":"¿Cuál es la respuesta corta CORRECTA a ''Is she a doctor?''"}','{"text":"Yes, she is."}','["Yes, she''s.","Yes, is.","Yes, she is a doctor."]','{"es":"En respuestas cortas afirmativas, NUNCA se usa contracción al final: ''Yes, she is'' (✓), NO ''Yes, she''s'' (✗). La respuesta completa siempre es Yes/No + pronombre + verbo (+ not para negativo)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0005-000000000001','00000002-0000-0000-0009-000000000003',5,'multiple_choice','{"text":"¿Cómo se pregunta ''¿Cuántos años tiene ella?'' en inglés?"}','{"text":"How old is she?"}','["How years is she?","How old she is?","What is her age?"]','{"es":"''How old is she?'' es la forma correcta. ''How years is she?'' es un error de traducción directa del español. ''What is her age?'' es demasiado formal. Para la edad usamos siempre ''How old + To Be''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0006-000000000001','00000002-0000-0000-0009-000000000003',6,'fill_blank','{"text":"___ your parents at home? — No, they ___. They''re at work."}','{"text":"Are / aren''t","accepted":["Are / aren''t","Are / are not"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0007-000000000001','00000002-0000-0000-0009-000000000003',7,'translation','{"text":"¿Es usted el director? — Sí, lo soy."}','{"text":"Are you the director? — Yes, I am.","accepted":["Are you the director? — Yes, I am.","Are you the manager? — Yes, I am."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0003-0008-000000000001','00000002-0000-0000-0009-000000000003',8,'translation','{"text":"¿Dónde está el baño? — Está al final del pasillo."}','{"text":"Where is the bathroom? — It''s at the end of the hallway.","accepted":["Where is the bathroom? — It''s at the end of the hallway.","Where''s the bathroom? — It is at the end of the corridor.","Where is the restroom? — It''s at the end of the hall."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0001-000000000001','00000002-0000-0000-0009-000000000004',1,'flashcard','{"text":"She is a lawyer","subtext":"¿Cuál es el artículo correcto antes de ''lawyer''?"}','{"text":"a — porque ''lawyer'' empieza con consonante /l/","phonetic":"/ʃiːz ə ˈlɔːjər/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0002-000000000001','00000002-0000-0000-0009-000000000004',2,'flashcard','{"text":"He is an engineer","subtext":"¿Por qué ''an'' y no ''a''?"}','{"text":"an — porque ''engineer'' empieza con sonido vocal /ɛ/","phonetic":"/hiːz ən ˌɛndʒɪˈnɪər/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0003-000000000001','00000002-0000-0000-0009-000000000004',3,'multiple_choice','{"text":"¿Cuál es correcto? ''Soy médico.''"}','{"text":"I''m a doctor."}','["I''m doctor.","I''m the doctor.","I''m an doctor."]','{"es":"Las profesiones en inglés necesitan artículo indefinido A/AN cuando van con To Be: ''I''m A doctor''. Sin artículo es incorrecto. AN se usa antes de vocal, A antes de consonante: ''a doctor'' (d=consonante), ''an engineer'' (e=vocal)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0004-000000000001','00000002-0000-0000-0009-000000000004',4,'multiple_choice','{"text":"''She is ___ architect and ___ artist.''"}','{"text":"an / an"}','["a / a","a / an","an / a"]','{"es":"''Architect'' empieza con sonido vocal /ɑː/ → AN. ''Artist'' empieza con sonido vocal /ɑː/ → AN. Ambas palabras empiezan con vocal, así que ambas usan AN."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0005-000000000001','00000002-0000-0000-0009-000000000004',5,'multiple_choice','{"text":"¿Cómo se dice ''Somos mexicanos'' en inglés?"}','{"text":"We''re Mexican."}','["We''re Mexicans.","We''re mexicans.","We are from Mexicans."]','{"es":"Los adjetivos de nacionalidad en inglés NO tienen forma plural: ''We''re Mexican'' (no ''Mexicans''). Además, siempre se escriben con MAYÚSCULA: ''Mexican'', no ''mexican''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0006-000000000001','00000002-0000-0000-0009-000000000004',6,'fill_blank','{"text":"My name is Sofia. I''m ___ architect from Buenos Aires. I''m ___ Argentine."}','{"text":"an / (empty)","accepted":["an /"]}',NULL,'{"es":"Ante ''architect'' que empieza con vocal usamos AN. Para la nacionalidad como adjetivo no necesita artículo: ''I''m Argentine'' (soy argentina)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0007-000000000001','00000002-0000-0000-0009-000000000004',7,'translation','{"text":"Mi jefe es alemán. Es un ingeniero muy experimentado."}','{"text":"My boss is German. He''s a very experienced engineer.","accepted":["My boss is German. He''s a very experienced engineer.","My boss is German. He is a very experienced engineer."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0004-0008-000000000001','00000002-0000-0000-0009-000000000004',8,'translation','{"text":"¿De dónde es ella? — Es brasileña. Es profesora de portugués."}','{"text":"Where is she from? — She''s Brazilian. She''s a Portuguese teacher.","accepted":["Where is she from? — She''s Brazilian. She''s a Portuguese teacher.","Where is she from? — She is Brazilian. She is a Portuguese teacher."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0001-000000000001','00000002-0000-0000-0009-000000000005',1,'flashcard','{"text":"I''m exhausted","subtext":"Estado físico extremo — más fuerte que ''tired''"}','{"text":"Estoy agotado/a (completamente sin energía)","phonetic":"/aɪm ɪɡˈzɔːstɪd/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0002-000000000001','00000002-0000-0000-0009-000000000005',2,'flashcard','{"text":"She''s furious","subtext":"Estado emocional intenso — más fuerte que ''angry''"}','{"text":"Ella está furiosa (muy enojada)","phonetic":"/ʃiːz ˈfjʊəriəs/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0003-000000000001','00000002-0000-0000-0009-000000000005',3,'multiple_choice','{"text":"¿Cómo describes a alguien que mide 1.95m en inglés?"}','{"text":"He''s very tall."}','["He''s very high.","He has very tall.","He''s very length."]','{"es":"En inglés usamos TALL para la altura de personas: ''He''s tall''. HIGH se usa para objetos o lugares (''a high mountain''). Para personas siempre TALL. Con To Be + adjetivo: ''He''s very tall''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0004-000000000001','00000002-0000-0000-0009-000000000005',4,'multiple_choice','{"text":"''I''m ___ nervous about the presentation. I''m ___ scared.'' (un poco / bastante)"}','{"text":"a bit / quite"}','["very / a bit","so / a little","quite / very"]','{"es":"A BIT y A LITTLE significan ''un poco'' (suavizan el adjetivo). QUITE significa ''bastante'' (intensidad moderada). VERY y SO son los más intensos. En este contexto: ''un poco nervioso'' = ''a bit nervous'' y ''bastante asustado'' = ''quite scared''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0005-000000000001','00000002-0000-0000-0009-000000000005',5,'multiple_choice','{"text":"¿Qué oración es correcta en inglés?"}','{"text":"The food is delicious and the service is excellent."}','["The food are delicious and the service are excellent.","The food is delicious and the service are excellent.","The foods is delicious and the services is excellent."]','{"es":"''Food'' y ''service'' son sustantivos singulares (incontable e incontable), así que usan IS. Los adjetivos en inglés (''delicious'', ''excellent'') no cambian — misma forma para singular y plural."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0006-000000000001','00000002-0000-0000-0009-000000000005',6,'fill_blank','{"text":"The children ___ very excited. It ___ Christmas tomorrow!"}','{"text":"are / is","accepted":["are / is"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0007-000000000001','00000002-0000-0000-0009-000000000005',7,'translation','{"text":"Estoy un poco cansado pero muy feliz. El viaje fue increíble."}','{"text":"I''m a bit tired but very happy. The trip was incredible.","accepted":["I''m a bit tired but very happy. The trip was incredible.","I''m a little tired but very happy. The trip was amazing."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0005-0008-000000000001','00000002-0000-0000-0009-000000000005',8,'translation','{"text":"El apartamento es pequeño pero muy acogedor y bastante limpio."}','{"text":"The apartment is small but very cozy and quite clean.","accepted":["The apartment is small but very cozy and quite clean.","The apartment is small but very cosy and quite clean."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0001-000000000001','00000002-0000-0000-0009-000000000006',1,'flashcard','{"text":"I''m hungry","subtext":"Error clásico: NO ''I have hungry'' — ¿por qué?"}','{"text":"Tengo hambre — en inglés hunger es adjetivo, no sustantivo con tener","phonetic":"/aɪm ˈhʌŋɡri/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0002-000000000001','00000002-0000-0000-0009-000000000006',2,'flashcard','{"text":"She''s 35 years old","subtext":"Error clásico: NO ''She has 35 years''"}','{"text":"Ella tiene 35 años — la edad usa TO BE en inglés","phonetic":"/ʃiːz ˈθɜːtifaɪv jɪərz oʊld/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0003-000000000001','00000002-0000-0000-0009-000000000006',3,'multiple_choice','{"text":"¿Cómo se dice ''Tengo frío'' en inglés?"}','{"text":"I''m cold."}','["I have cold.","I have coldness.","I am having cold."]','{"es":"''Tener frío'' en inglés = ''to be cold''. En inglés las sensaciones físicas como el frío, el calor, el hambre y la sed se expresan con TO BE + adjetivo, no con HAVE + sustantivo como en español."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0004-000000000001','00000002-0000-0000-0009-000000000006',4,'multiple_choice','{"text":"''¡Tenemos prisa! El tren sale en 5 minutos.''"}','{"text":"We''re in a hurry! The train leaves in 5 minutes."}','["We have hurry! The train leaves in 5 minutes.","We are hurry! The train leaves in 5 minutes.","We''re hurried! The train leaves in 5 minutes."]','{"es":"''Tener prisa'' = ''to be in a hurry'' (ser/estar con prisa). La preposición IN es obligatoria aquí: ''in a hurry''. ''We have hurry'' es una traducción literal incorrecta."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0005-000000000001','00000002-0000-0000-0009-000000000006',5,'multiple_choice','{"text":"¿Cuántas de estas oraciones son CORRECTAS en inglés? (1) ''I''m 28.'' (2) ''I have 28 years.'' (3) ''I am thirsty.'' (4) ''I have thirst.''"}','{"text":"Solo 2: ''I''m 28'' y ''I am thirsty.''"}','["Las 4 son correctas","Solo 1: ''I''m 28''","Las 4 son incorrectas"]','{"es":"En inglés: edad = TO BE (''I''m 28'' ✓), no HAVE (''I have 28 years'' ✗). Sensaciones = TO BE + adjetivo (''I am thirsty'' ✓), no HAVE + sustantivo (''I have thirst'' ✗)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0006-000000000001','00000002-0000-0000-0009-000000000006',6,'fill_blank','{"text":"Excuse me, I ___ very thirsty. ___ there any water? I ___ also a bit hungry."}','{"text":"am / Is / am","accepted":["am / Is / am"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0007-000000000001','00000002-0000-0000-0009-000000000006',7,'translation','{"text":"Tengo razón. El banco está cerrado. Son las 6 de la tarde."}','{"text":"I''m right. The bank is closed. It''s 6 pm.","accepted":["I''m right. The bank is closed. It''s 6 pm.","I am right. The bank is closed. It is 6 pm."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0009-0006-0008-000000000001','00000002-0000-0000-0009-000000000006',8,'translation','{"text":"¿Tienes miedo? No tengas miedo. El perro es muy amable."}','{"text":"Are you afraid? Don''t be afraid. The dog is very friendly.","accepted":["Are you afraid? Don''t be afraid. The dog is very friendly.","Are you scared? Don''t be scared. The dog is very friendly.","Are you scared? Don''t worry. The dog is very friendly."]}',NULL,NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0010-000000000001','00000001-0000-0000-0000-000000000010','00000000-0000-0000-0001-000000000001',1,'articulo-indefinido-a-an','{"es":"Artículo Indefinido: A y AN","en":"Indefinite Article: A and AN"}','{"es":"Aprende cuándo usar A y cuándo usar AN — la regla es más simple de lo que parece.","en":"Learn when to use A and when to use AN — the rule is simpler than it seems."}','theory_practice',20,15,'{"intro":"En inglés hay dos artículos indefinidos: A y AN. Ambos significan ''un'' o ''una'' en español. La diferencia entre ellos no es de significado sino de pronunciación: A se usa antes de sonido consonántico y AN se usa antes de sonido vocálico. La clave está en el SONIDO, no en la letra escrita.","sections":[{"type":"explanation","title":"LA REGLA FUNDAMENTAL: EL SONIDO, NO LA LETRA","text":"A se usa antes de palabras que comienzan con sonido CONSONÁNTICO: a book, a car, a person, a university (''you-ni-ver-si-ty'' empieza con sonido /j/ = consonante!), a European city (''you-ro-pi-an'' empieza con /j/). AN se usa antes de palabras que comienzan con sonido VOCÁLICO: an apple, an orange, an umbrella, an hour (la H es silenciosa — ''our'' empieza con /aʊ/ = vocal!), an honest man (H silenciosa)."},{"type":"table","title":"A vs AN — EJEMPLOS CLAVE","headers":["Artículo","Razón","Ejemplos"],"rows":[["a","consonante inicial","a book, a car, a dog, a table, a friend"],["a","vocal ESCRITA pero consonante SONIDO","a university /juː/, a European /juː/, a one-hour /w/"],["an","vocal inicial","an apple, an egg, an island, an orange, an umbrella"],["an","H silenciosa (sonido vocal)","an hour /aʊr/, an honest person, an heir"],["an","A inicial en sigla que se lee letra a letra","an MBA /ɛm/, an NGO /ɛn/, an MP /ɛm/"]]},{"type":"explanation","title":"CUÁNDO USAR A/AN","text":"A/AN se usan para hablar de algo por primera vez o de forma indefinida (''un'' objeto cualquiera, no uno específico). Se usan con profesiones: ''She''s a teacher'' (es maestra). Para describir algo de una categoría: ''It''s a Japanese restaurant'' (es un restaurante japonés). Para decir que algo es único dentro de una categoría: ''He''s a real genius'' (es un verdadero genio)."},{"type":"examples","title":"EJEMPLOS EN CONTEXTO","items":[{"label":"Primera mención","en":"I saw a dog in the park. The dog was very friendly.","es":"Vi un perro en el parque. El perro era muy amable."},{"label":"Profesión","en":"She''s an accountant. He''s a software developer.","es":"Ella es contadora. Él es desarrollador de software."},{"label":"Descripción","en":"It''s a great movie. It''s an amazing story.","es":"Es una gran película. Es una historia increíble."},{"label":"Trampa: U inicial","en":"It''s a university — NOT ''an university'' (suena /juː/)","es":"Es una universidad — la U suena como consonante /j/"}]},{"type":"note","variant":"tip","text":"La trampa más común: UNIVERSITY y EUROPEAN empiezan con la letra U/E pero el SONIDO es /j/ (como en ''yes''), que es consonante. Entonces: ''a university'', ''a European country''. Otra trampa: HOUR empieza con H pero se pronuncia /aʊr/ (la H es muda), entonces: ''an hour''."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0010-000000000002','00000001-0000-0000-0000-000000000010','00000000-0000-0000-0001-000000000001',2,'articulo-definido-the','{"es":"Artículo Definido: THE","en":"The Definite Article: THE"}','{"es":"Aprende cuándo usar THE — el artículo que indica algo específico, único o ya mencionado.","en":"Learn when to use THE — the article that indicates something specific, unique, or already mentioned."}','theory_practice',20,15,'{"intro":"THE es el artículo definido en inglés — equivale al español ''el'', ''la'', ''los'', ''las''. A diferencia del español, en inglés solo hay UNA forma: THE sirve para masculino, femenino, singular y plural. Se pronuncia /ðə/ antes de consonante y /ðiː/ antes de vocal. THE indica que tanto el hablante como el oyente saben de qué se está hablando.","sections":[{"type":"explanation","title":"CUÁNDO USAR THE: CUATRO REGLAS","text":"1) SEGUNDA MENCIÓN: cuando ya mencionaste algo con a/an, la siguiente vez usas THE. ''I have a cat. The cat is black.'' 2) ÚNICO EN SU ESPECIE: ''the sun'', ''the moon'', ''the sky'', ''the internet'', ''the president'' (cuando hay solo uno en el contexto). 3) CUANDO AMBOS SABEN: si el oyente sabe exactamente a qué te refieres: ''Pass me the salt'' (la sal que está en la mesa, que ambos ven). 4) CON SUPERLATIVOS: ''the best'', ''the most important'', ''the tallest building''."},{"type":"table","title":"USOS DE THE","headers":["Uso","Ejemplo en inglés","Traducción"],"rows":[["Segunda mención","I saw a dog. The dog was huge.","Vi un perro. El perro era enorme."],["Único","The sun is a star. The moon is beautiful.","El sol es una estrella. La luna es hermosa."],["Conocido por ambos","Can you close the door? Pass me the menu.","¿Puedes cerrar la puerta? Pásame el menú."],["Superlativo","She''s the best student in the class.","Ella es la mejor estudiante de la clase."],["Adjetivos sustantivados","The rich and the poor live differently.","Los ricos y los pobres viven diferente."],["Nombres de océanos/ríos/montañas","The Atlantic. The Amazon. The Alps.","El Atlántico. El Amazonas. Los Alpes."]]},{"type":"explanation","title":"CUÁNDO NO USAR THE","text":"NO se usa THE con: nombres propios de personas (''Maria is here'' — no ''the Maria''), países en general (''I''m from Mexico'' — no ''from the Mexico'', excepciones: ''the USA'', ''the UK'', ''the Philippines''), idiomas (''I speak English'' — no ''the English''), comidas en general (''I love pizza'' — no ''the pizza''), deportes (''She plays tennis'' — no ''the tennis'')."},{"type":"examples","title":"THE EN CONVERSACIÓN","items":[{"label":"Historia con a/an → the","en":"I bought a new laptop. The laptop is amazing. The screen is very bright.","es":"Compré una laptop nueva. La laptop es increíble. La pantalla es muy brillante."},{"label":"Único","en":"The president of France is in Spain. The weather is good there.","es":"El presidente de Francia está en España. El clima está bien allá."},{"label":"Superlativo","en":"That was the best meal I''ve ever had!","es":"¡Esa fue la mejor comida que he tenido en mi vida!"},{"label":"NO usar the","en":"I love Spanish. I eat pizza every Friday. Mexico is beautiful.","es":"Me encanta el español. Como pizza todos los viernes. México es hermoso."}]},{"type":"note","variant":"warning","text":"Excepciones de países con THE: ''the USA'' (the United States of America), ''the UK'' (the United Kingdom), ''the Philippines'', ''the Netherlands''. Estos países llevan THE porque sus nombres son descriptivos o plurales. Todos los demás países van sin artículo."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0010-000000000003','00000001-0000-0000-0000-000000000010','00000000-0000-0000-0001-000000000001',3,'plurales-en-ingles','{"es":"Plurales en Inglés","en":"Plurals in English"}','{"es":"Aprende las reglas para formar plurales en inglés: regulares e irregulares.","en":"Learn the rules for forming plurals in English: regular and irregular."}','theory_practice',20,15,'{"intro":"Para hablar de más de una cosa en inglés necesitas saber cómo formar el plural. Hay reglas regulares claras (la mayoría de las palabras) y una lista de plurales irregulares que debes memorizar. Los plurales son fundamentales para casi todas las conversaciones cotidianas.","sections":[{"type":"explanation","title":"REGLAS PARA EL PLURAL REGULAR","text":"La regla general es añadir -S al final: book→books, car→cars, phone→phones. Reglas especiales: Palabras que terminan en -s, -ss, -sh, -ch, -x, -z añaden -ES: bus→buses, glass→glasses, dish→dishes, church→churches, box→boxes. Palabras que terminan en consonante + Y cambian la Y por I y añaden -ES: city→cities, baby→babies, party→parties. Palabras que terminan en vocal + Y solo añaden -S: day→days, boy→boys, key→keys. Palabras que terminan en -f/-fe cambian a -VES: leaf→leaves, knife→knives, life→lives."},{"type":"table","title":"PLURALES IRREGULARES ESENCIALES","headers":["Singular","Plural","Traducción","Nota"],"rows":[["man","men","hombre / hombres","Vocal cambia o→e"],["woman","women","mujer / mujeres","Vocal cambia o→e"],["child","children","niño / niños","Plural completamente diferente"],["person","people","persona / personas","Palabra diferente para plural"],["foot","feet","pie / pies","Vocal cambia oo→ee"],["tooth","teeth","diente / dientes","Vocal cambia oo→ee"],["mouse","mice","ratón / ratones","Vocal cambia completely"],["fish","fish","pez / peces","Sin cambio (mismo en singular y plural)"],["sheep","sheep","oveja / ovejas","Sin cambio"],["deer","deer","venado / venados","Sin cambio"]]},{"type":"examples","title":"PLURALES EN ORACIONES","items":[{"label":"Regular -S","en":"The children have two cats and three dogs.","es":"Los niños tienen dos gatos y tres perros."},{"label":"Irregular","en":"Two men and three women are waiting in the office.","es":"Dos hombres y tres mujeres esperan en la oficina."},{"label":"Irregular sin cambio","en":"We saw many fish in the river. Three deer were nearby.","es":"Vimos muchos peces en el río. Tres venados estaban cerca."},{"label":"Terminación -ies","en":"How many cities are there in the USA? About 20,000.","es":"¿Cuántas ciudades hay en EE.UU.? Alrededor de 20.000."}]},{"type":"note","variant":"tip","text":"PERSON → PEOPLE es un plural muy especial. ''People'' es técnicamente un plural: ''One person is here'' vs ''Many people are here'' (people + ARE, no IS). Evita decir ''peoples'' (incorrecto en la mayoría de contextos) — ''people'' ya es plural."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0010-000000000004','00000001-0000-0000-0000-000000000010','00000000-0000-0000-0001-000000000001',4,'sustantivos-contables-incontables','{"es":"Sustantivos Contables e Incontables","en":"Countable and Uncountable Nouns"}','{"es":"Entiende la diferencia entre sustantivos que se cuentan y los que no, y cómo usar some, any y a lot of.","en":"Understand the difference between nouns you can count and those you can''t, and how to use some, any, and a lot of."}','theory_practice',20,15,'{"intro":"En inglés, los sustantivos se dividen en dos grandes grupos: contables (que tienen singular y plural) e incontables (que no tienen plural y no se usan con a/an). Esta distinción afecta qué artículos, cuantificadores y verbos puedes usar con ellos. Entender esta diferencia es clave para hablar inglés correctamente.","sections":[{"type":"explanation","title":"SUSTANTIVOS CONTABLES","text":"Los sustantivos contables son cosas que puedes contar individualmente: one book, two books, three books. Tienen forma singular y plural. Se pueden usar con a/an: ''a book'', ''an apple''. Se pueden usar con números: ''three dogs'', ''five houses''. Se pueden usar con ''many'' y ''few'': ''many cars'', ''few problems''. En oraciones negativas e interrogativas: ''Are there any books?'' / ''There aren''t any books.''"},{"type":"explanation","title":"SUSTANTIVOS INCONTABLES","text":"Los sustantivos incontables representan masas, sustancias, conceptos abstractos o colecciones no individuales. NO tienen plural. NO se usan con a/an. NO se usan con números directamente. Ejemplos: water (agua), milk (leche), rice (arroz), bread (pan), money (dinero), information (información), advice (consejo), music (música), love (amor), furniture (muebles), luggage (equipaje), weather (clima). Para cuantificarlos usas expresiones como ''a glass of water'', ''a piece of advice'', ''a lot of money''."},{"type":"table","title":"CUANTIFICADORES: CONTABLES vs INCONTABLES","headers":["Cuantificador","Con contables","Con incontables","Significado"],"rows":[["some","some books (afirmativo)","some water (afirmativo)","algo de / unos/as"],["any","any books? (pregunta/neg)","any water? (pregunta/neg)","algún/alguna (preguntas y negaciones)"],["a lot of","a lot of cars","a lot of money","mucho/a, muchos/as"],["many","many books","✗ no se usa","muchos/as (solo contables)"],["much","✗ no se usa","much water","mucho/a (solo incontables)"],["a few","a few books","✗ no se usa","unos pocos (contables)"],["a little","✗ no se usa","a little water","un poco de (incontables)"]]},{"type":"examples","title":"EJEMPLOS PRÁCTICOS","items":[{"label":"Contable","en":"I need some books. Do you have any dictionaries?","es":"Necesito algunos libros. ¿Tienes algún diccionario?"},{"label":"Incontable","en":"I need some water. Is there any milk in the fridge?","es":"Necesito un poco de agua. ¿Hay leche en el refrigerador?"},{"label":"A lot of (ambos)","en":"There''s a lot of traffic. There are a lot of cars.","es":"Hay mucho tráfico. Hay muchos coches."},{"label":"Trampa","en":"Information is uncountable — NOT ''an information'' or ''informations''","es":"Information es incontable — NO ''una información'' ni ''informaciones''"}]},{"type":"note","variant":"warning","text":"Palabras que PARECEN contables pero son incontables en inglés: information (no ''informations''), advice (no ''advices''), furniture (no ''furnitures''), luggage/baggage (no ''luggages''), money (no ''moneys''), news (no ''a new''), homework (no ''homeworks''), research (no ''researches''). Memoriza esta lista — son errores muy comunes."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0010-000000000005','00000001-0000-0000-0000-000000000010','00000000-0000-0000-0001-000000000001',5,'articulo-cero','{"es":"Artículo Cero: Cuándo No Usar Artículo","en":"Zero Article: When Not to Use an Article"}','{"es":"Descubre los casos en inglés donde NO se usa ningún artículo — idiomas, deportes, comidas en general y más.","en":"Discover the cases in English where NO article is used — languages, sports, meals in general, and more."}','theory_practice',20,15,'{"intro":"En inglés hay situaciones donde no se usa ningún artículo (ni a/an ni the). A esto se le llama ''artículo cero''. Para un hispanohablante esto puede ser sorprendente porque en español casi siempre usamos algún artículo. Aprender cuándo NO usar artículo es tan importante como saber cuándo usarlo.","sections":[{"type":"explanation","title":"CUÁNDO NO SE USA ARTÍCULO","text":"No se usa artículo con: (1) IDIOMAS: I speak Spanish. She studies French. (NO ''the Spanish'') (2) DEPORTES Y ACTIVIDADES: I play football. She does yoga. He swims. (3) COMIDAS EN GENERAL: I love pizza. She eats rice every day. Breakfast is at 8. (4) NOMBRES PROPIOS DE PERSONAS: Maria is here. Is David ready? (5) PAÍSES (mayoría): Mexico is beautiful. France is in Europe. (6) MATERIAS DE ESTUDIO: She studies biology. I like mathematics."},{"type":"table","title":"ARTÍCULO CERO — EJEMPLOS","headers":["Categoría","Sin artículo (correcto)","Con artículo (error común)"],"rows":[["Idioma","I speak English.","I speak the English. ✗"],["Deporte","He plays basketball.","He plays the basketball. ✗"],["Comida en general","I love chocolate.","I love the chocolate. ✗"],["Nombre propio","Carlos is my friend.","The Carlos is my friend. ✗"],["País","Japan is amazing.","The Japan is amazing. ✗"],["Materia","She studies physics.","She studies the physics. ✗"],["Comida del día","Lunch is at 1pm.","The lunch is at 1pm. ✗"],["Transporte","I go by bus.","I go by the bus. ✗"]]},{"type":"explanation","title":"DIFERENCIA ENTRE GENERAL Y ESPECÍFICO","text":"La diferencia clave es GENERAL vs ESPECÍFICO. Sin artículo = general/categórico. Con THE = específico/particular. ''I love music'' (la música en general) vs ''I loved the music at the party'' (la música específica de esa fiesta). ''Dogs are friendly'' (los perros como especie) vs ''The dogs in that shelter are friendly'' (esos perros específicos). ''Coffee is my favorite drink'' (el café como bebida) vs ''The coffee here is excellent'' (este café específico)."},{"type":"examples","title":"GENERAL vs ESPECÍFICO EN CONTEXTO","items":[{"label":"General (sin artículo)","en":"I love coffee, especially in the morning.","es":"Me encanta el café, especialmente por la mañana."},{"label":"Específico (con the)","en":"The coffee in this café is the best I''ve ever tried.","es":"El café de esta cafetería es el mejor que he probado."},{"label":"General (sin artículo)","en":"Life is beautiful. Love is important.","es":"La vida es hermosa. El amor es importante."},{"label":"Específico (con the)","en":"The life of a doctor can be very demanding.","es":"La vida de un médico puede ser muy exigente."}]},{"type":"note","variant":"tip","text":"Una regla práctica: si puedes añadir ''en general'' al final de la frase y sigue teniendo sentido, probablemente no necesitas artículo. ''I love pizza (in general)'' = sin artículo. ''I love the pizza (in this specific place)'' = con THE."}]}','true');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0001-000000000001','00000002-0000-0000-0010-000000000001',1,'multiple_choice','{"text":"¿Cuál es correcto? ''Ella es ___ actriz muy talentosa.''"}','{"text":"an actress"}','["a actress","the actress","actress"]','{"es":"''Actress'' empieza con el sonido vocal /æ/, por eso usamos AN. A se usa antes de consonante, AN antes de vocal."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0002-000000000001','00000002-0000-0000-0010-000000000001',2,'multiple_choice','{"text":"''I need ___ umbrella and ___ raincoat.''"}','{"text":"an / a"}','["a / a","an / an","a / an"]','{"es":"''Umbrella'' empieza con vocal /ʌ/ → AN. ''Raincoat'' empieza con consonante /r/ → A."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0003-000000000001','00000002-0000-0000-0010-000000000001',3,'multiple_choice','{"text":"¿Cuál es CORRECTO? ''Es una universidad muy famosa.''"}','{"text":"It''s a university."}','["It''s an university.","It''s the university.","It''s an universities."]','{"es":"''University'' empieza con el sonido /j/ (como en ''yes'') — es consonante. Por eso usamos A, no AN. Esta es una de las trampas más famosas del inglés."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0004-000000000001','00000002-0000-0000-0010-000000000001',4,'multiple_choice','{"text":"''It takes ___ hour to get there.''"}','{"text":"an"}','["a","the","some"]','{"es":"''Hour'' se pronuncia /aʊər/ — la H es muda y el primer sonido es vocal /aʊ/. Por eso usamos AN. Es uno de los pocos casos donde la letra escrita (H consonante) no determina el artículo."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0005-000000000001','00000002-0000-0000-0010-000000000001',5,'fill_blank','{"text":"He''s ___ honest man and ___ great leader. He works in ___ European company."}','{"text":"an / a / a","accepted":["an / a / a"]}',NULL,'{"es":"''Honest'': H silenciosa → AN. ''Great'': consonante → A. ''European'': suena /juː-/ → A (consonante /j/)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0006-000000000001','00000002-0000-0000-0010-000000000001',6,'fill_blank','{"text":"I found ___ interesting article about ___ old city in Italy."}','{"text":"an / an","accepted":["an / an"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0007-000000000001','00000002-0000-0000-0010-000000000001',7,'translation','{"text":"Es un ingeniero muy habilidoso. Trabaja en una empresa alemana."}','{"text":"He''s a very skilled engineer. He works for a German company.","accepted":["He''s a very skilled engineer. He works for a German company.","He is a very skilled engineer. He works in a German company."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0001-0008-000000000001','00000002-0000-0000-0010-000000000001',8,'translation','{"text":"Necesito una hora para terminar. Es un trabajo importante."}','{"text":"I need an hour to finish. It''s an important job.","accepted":["I need an hour to finish. It''s an important job.","I need an hour to finish. It is an important job."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0001-000000000001','00000002-0000-0000-0010-000000000002',1,'multiple_choice','{"text":"''I have a cat. ___ cat is black and white.''"}','{"text":"The"}','["A","An","My"]','{"es":"Primera mención: ''a cat'' (un gato cualquiera). Segunda mención: THE cat (el gato específico que ya mencionamos). Esta es la regla de primera vs segunda mención."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0002-000000000001','00000002-0000-0000-0010-000000000002',2,'multiple_choice','{"text":"¿Cuál es correcto? ''___ sun is very hot today.''"}','{"text":"The sun is very hot today."}','["A sun is very hot today.","An sun is very hot today.","Sun is very hot today."]','{"es":"''The sun'' (el sol) lleva THE porque hay solo uno — es único en su especie. Lo mismo para: the moon, the sky, the earth, the internet, the universe."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0003-000000000001','00000002-0000-0000-0010-000000000002',3,'multiple_choice','{"text":"''She''s ___ best student in the school.''"}','{"text":"the"}','["a","an","(sin artículo)"]','{"es":"Con superlativos SIEMPRE se usa THE: the best, the worst, the most beautiful, the tallest. Los superlativos implican unicidad — hay solo uno que es ''el mejor''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0004-000000000001','00000002-0000-0000-0010-000000000002',4,'multiple_choice','{"text":"¿Cuándo NO se usa THE? (elige el ejemplo correcto)"}','{"text":"I speak Japanese. I love coffee. Brazil is large."}','["I speak the Japanese. I love the coffee. The Brazil is large.","I speak Japanese. I love the coffee. Brazil is large.","I speak the Japanese. I love coffee. Brazil is large."]','{"es":"Sin artículo con: idiomas (Japanese), comida en general (coffee), países (Brazil). Estos tres usan artículo cero, no THE."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0005-000000000001','00000002-0000-0000-0010-000000000002',5,'fill_blank','{"text":"I live near ___ river. ___ river goes through the whole city. It''s ___ longest river in the country."}','{"text":"a / The / the","accepted":["a / The / the"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0006-000000000001','00000002-0000-0000-0010-000000000002',6,'fill_blank','{"text":"Can you pass me ___ salt, please? And ___ pepper too, if you don''t mind."}','{"text":"the / the","accepted":["the / the"]}',NULL,'{"es":"The salt y the pepper porque están en la mesa frente a ambos — el oyente sabe exactamente a qué objetos nos referimos."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0007-000000000001','00000002-0000-0000-0010-000000000002',7,'translation','{"text":"El presidente de México está en la ciudad. La reunión es en el hotel central."}','{"text":"The president of Mexico is in the city. The meeting is at the central hotel.","accepted":["The president of Mexico is in the city. The meeting is at the central hotel."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0002-0008-000000000001','00000002-0000-0000-0010-000000000002',8,'translation','{"text":"Ese fue el mejor viaje de mi vida. El hotel era increíble y la playa era perfecta."}','{"text":"That was the best trip of my life. The hotel was incredible and the beach was perfect.","accepted":["That was the best trip of my life. The hotel was incredible and the beach was perfect."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0001-000000000001','00000002-0000-0000-0010-000000000003',1,'multiple_choice','{"text":"¿Cuál es el plural de ''child'' (niño)?"}','{"text":"children"}','["childs","childes","childre"]','{"es":"''Child → children'' es uno de los plurales irregulares más importantes. No sigue ninguna regla regular — hay que memorizarlo. Lo mismo con man/men, woman/women, tooth/teeth."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0002-000000000001','00000002-0000-0000-0010-000000000003',2,'multiple_choice','{"text":"¿Cuál es el plural correcto de ''city''?"}','{"text":"cities"}','["citys","cityes","city"]','{"es":"''City'' termina en consonante (T) + Y. Regla: consonante + Y → quita la Y y añade -IES. city→cities, baby→babies, party→parties, country→countries."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0003-000000000001','00000002-0000-0000-0010-000000000003',3,'multiple_choice','{"text":"¿Cuál oración tiene el plural CORRECTO?"}','{"text":"There are many people in the square."}','["There are many peoples in the square.","There is many people in the square.","There are many person in the square."]','{"es":"''People'' es el plural de ''person'' y ya es plural — nunca se dice ''peoples'' en este contexto. ''People'' + verbo plural: ''people ARE'', no ''people IS''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0004-000000000001','00000002-0000-0000-0010-000000000003',4,'multiple_choice','{"text":"¿Cuál es el plural de ''knife'' (cuchillo)?"}','{"text":"knives"}','["knifes","knifes","knife"]','{"es":"Palabras que terminan en -FE cambian a -VES: knife→knives, wife→wives, life→lives, leaf→leaves. Es una regla especial que afecta a un pequeño grupo de palabras."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0005-000000000001','00000002-0000-0000-0010-000000000003',5,'fill_blank','{"text":"There are three ___ (man) and five ___ (woman) in my team. We have two ___ (child) each."}','{"text":"men / women / children","accepted":["men / women / children"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0006-000000000001','00000002-0000-0000-0010-000000000003',6,'fill_blank','{"text":"I visited five ___ (country) in Europe. The ___ (city) were all beautiful."}','{"text":"countries / cities","accepted":["countries / cities"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0007-000000000001','00000002-0000-0000-0010-000000000003',7,'translation','{"text":"Hay muchos niños en el parque. Las mujeres hablan con los hombres."}','{"text":"There are many children in the park. The women talk with the men.","accepted":["There are many children in the park. The women talk with the men.","There are many children in the park. The women are talking with the men."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0003-0008-000000000001','00000002-0000-0000-0010-000000000003',8,'translation','{"text":"Las ciudades más grandes del país tienen millones de personas."}','{"text":"The largest cities in the country have millions of people.","accepted":["The largest cities in the country have millions of people.","The biggest cities in the country have millions of people."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0001-000000000001','00000002-0000-0000-0010-000000000004',1,'multiple_choice','{"text":"¿Cuál es INCONTABLE en inglés?"}','{"text":"information"}','["book","car","question"]','{"es":"''Information'' es incontable — nunca ''informations'' ni ''an information''. Para hablar de una unidad dices ''a piece of information''. Lo mismo con: advice, furniture, luggage, money, news."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0002-000000000001','00000002-0000-0000-0010-000000000004',2,'multiple_choice','{"text":"¿Cuál es correcto? ''No tengo dinero.''"}','{"text":"I don''t have any money."}','["I don''t have any moneys.","I don''t have some money.","I don''t have a money."]','{"es":"''Money'' es incontable: nunca ''moneys''. En oraciones negativas usamos ANY, no SOME. Y sin artículo a/an porque es incontable."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0003-000000000001','00000002-0000-0000-0010-000000000004',3,'multiple_choice','{"text":"¿Qué cuantificador va con sustantivos CONTABLES en plural?"}','{"text":"many — ''many books'', ''many cars'', ''many people''"}','["much — ''much books''","a little — ''a little books''","less — ''less books''"]','{"es":"MANY va con sustantivos contables plurales: ''many books''. MUCH va con incontables: ''much water''. Este es uno de los errores más comunes: ''much books'' (incorrecto) → ''many books'' (correcto)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0004-000000000001','00000002-0000-0000-0010-000000000004',4,'multiple_choice','{"text":"''Is there ___ milk? I''d like ___ coffee.''"}','{"text":"any / some"}','["some / any","many / much","a few / a little"]','{"es":"En preguntas/negaciones usamos ANY. En afirmaciones (''I''d like'' = me gustaría, afirmativo) usamos SOME. Esta distinción some/any es fundamental."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0005-000000000001','00000002-0000-0000-0010-000000000004',5,'fill_blank','{"text":"I need ___ advice. Do you have ___ time? I have ___ questions about the project."}','{"text":"some / any / some","accepted":["some / any / some"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0006-000000000001','00000002-0000-0000-0010-000000000004',6,'fill_blank','{"text":"There isn''t ___ furniture in the apartment. There are only ___ chairs and ___ small table."}','{"text":"any / a few / a","accepted":["any / a few / a"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0007-000000000001','00000002-0000-0000-0010-000000000004',7,'translation','{"text":"¿Tienes alguna información sobre el vuelo? Necesito algunos detalles."}','{"text":"Do you have any information about the flight? I need some details.","accepted":["Do you have any information about the flight? I need some details.","Do you have any information about the flight? I need some detail."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0004-0008-000000000001','00000002-0000-0000-0010-000000000004',8,'translation','{"text":"Hay mucha gente aquí. No hay mucho espacio para todos."}','{"text":"There are a lot of people here. There isn''t much space for everyone.","accepted":["There are a lot of people here. There isn''t much space for everyone.","There are many people here. There''s not much space for everyone."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0001-000000000001','00000002-0000-0000-0010-000000000005',1,'multiple_choice','{"text":"¿Cuál es correcto? ''Hablo español.''"}','{"text":"I speak Spanish."}','["I speak the Spanish.","I speak a Spanish.","I speak an Spanish."]','{"es":"Los idiomas van sin artículo en inglés: I speak Spanish/English/French. Nunca ''the Spanish'' cuando te refieres al idioma. (Sí se puede decir ''the Spanish'' refiriéndose a los españoles como colectivo, pero es un uso diferente.)"}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0002-000000000001','00000002-0000-0000-0010-000000000005',2,'multiple_choice','{"text":"''___ life is short. Enjoy ___ little things.''"}','{"text":"(sin artículo) Life / the little things"}','["The life / a little things","A life / the little things","Life / a little things"]','{"es":"''Life'' en general = sin artículo. ''The little things'' = las cosas pequeñas específicas de nuestra vida (conocidas por el contexto). Life en general no lleva artículo; the little things lleva THE por ser específico."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0003-000000000001','00000002-0000-0000-0010-000000000005',3,'multiple_choice','{"text":"¿Cuál de estas NO necesita artículo?"}','{"text":"I eat breakfast at 7am."}','["I love the pizza at this place.","The coffee is cold.","Can I have the check, please?"]','{"es":"''Breakfast'' como comida del día general no lleva artículo: ''I eat breakfast'' (desayuno en general). Las otras tres sí llevan THE porque son específicas."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0004-000000000001','00000002-0000-0000-0010-000000000005',4,'multiple_choice','{"text":"''___ dogs are loyal animals.'' ¿Qué artículo va?"}','{"text":"(sin artículo) — hablamos de los perros en general"}','["The dogs are loyal animals.","A dogs are loyal animals.","Some dogs are loyal animals."]','{"es":"Cuando hablas de una especie o categoría en general, no usas artículo: ''Dogs are loyal'' (los perros son leales — como especie). Esto es diferente de ''The dogs in my street are loud'' (los perros específicos de mi calle)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0005-000000000001','00000002-0000-0000-0010-000000000005',5,'fill_blank','{"text":"___ music is my passion. I play ___ guitar and I love ___ jazz especially."}','{"text":"Music / the / (nothing)","accepted":["Music / the /"]}',NULL,'{"es":"Music en general = sin artículo. The guitar = el instrumento específico (es convencional en inglés decir ''play the guitar'', ''play the piano''). Jazz en general = sin artículo."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0006-000000000001','00000002-0000-0000-0010-000000000005',6,'fill_blank','{"text":"___ love is the most important thing in life. ___ love between these two people is very special."}','{"text":"Love / The love","accepted":["Love / The love"]}',NULL,'{"es":"''Love'' en general = sin artículo. ''The love between these two people'' = amor específico de personas específicas → THE."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0007-000000000001','00000002-0000-0000-0010-000000000005',7,'translation','{"text":"Me encanta la música. Toco el piano y el violín. Estudio en una escuela de música."}','{"text":"I love music. I play the piano and the violin. I study at a music school.","accepted":["I love music. I play the piano and the violin. I study at a music school."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0010-0005-0008-000000000001','00000002-0000-0000-0010-000000000005',8,'translation','{"text":"El café de este lugar es el mejor. En general, el café colombiano es excelente."}','{"text":"The coffee in this place is the best. In general, Colombian coffee is excellent.","accepted":["The coffee in this place is the best. In general, Colombian coffee is excellent.","The coffee here is the best. Generally, Colombian coffee is excellent."]}',NULL,NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0011-000000000001','00000001-0000-0000-0000-000000000011','00000000-0000-0000-0001-000000000001',1,'pronombres-sujeto','{"es":"Pronombres Sujeto","en":"Subject Pronouns"}','{"es":"Aprende I, you, he, she, it, we, they — cuándo y cómo usar cada pronombre sujeto en inglés.","en":"Learn I, you, he, she, it, we, they — when and how to use each subject pronoun in English."}','theory_practice',20,15,'{"intro":"Los pronombres sujeto reemplazan al sustantivo que realiza la acción en una oración. En inglés es OBLIGATORIO usarlos — no puedes omitir el sujeto como en español. ''Es un médico'' en español puede prescindir del ''él'', pero en inglés ''Is a doctor'' sería incorrecto: debes decir ''He is a doctor''. Dominar los pronombres sujeto es fundamental para construir cualquier oración en inglés.","sections":[{"type":"table","title":"LOS 7 PRONOMBRES SUJETO","headers":["Pronombre","Equivalente español","Uso","Ejemplo"],"rows":[["I","yo","Primera persona singular — siempre en MAYÚSCULA","I am from Mexico."],["you","tú / usted / ustedes / vosotros","Segunda persona — singular Y plural en inglés","You are my friend. / You are all welcome."],["he","él","Tercera persona masc. — personas masculinas","He is my brother."],["she","ella","Tercera persona fem. — personas femeninas","She is my sister."],["it","ello (no tiene equiv. directo)","Cosas, animales (sin género), ideas, el tiempo","It is cold. / It is my cat."],["we","nosotros/as","Primera persona plural","We are students."],["they","ellos/ellas / esas cosas","Tercera persona plural — personas Y cosas","They are my parents. / They are on sale."]]},{"type":"explanation","title":"EL PRONOMBRE IT — EL MÁS DIFERENTE","text":"IT es el pronombre que más confunde a los hispanohablantes porque en español rara vez se expresa explícitamente. IT se usa para: cosas y objetos (''It''s a phone''), animales cuando no se conoce el sexo (''The cat is tired. It needs rest''), el clima (''It''s raining'', ''It''s 25 degrees''), la hora (''It''s 3pm''), la fecha (''It''s Monday''), la distancia (''It''s 2 km from here''). También se usa como sujeto impersonal: ''It''s important to study''."},{"type":"explanation","title":"YOU — UN PRONOMBRE PARA TODO","text":"YOU es el mismo pronombre para TÚ, USTED, VOSOTROS y USTEDES. El inglés no distingue entre formal e informal en el pronombre. Para saber si es singular o plural dependes del contexto. Cuando quieres clarificar que es plural puedes añadir ''you all'' o ''you guys'' (informal) o ''all of you'' (formal): ''You all are welcome!'' = ¡Bienvenidos todos!"},{"type":"explanation","title":"EL SUJETO ES OBLIGATORIO EN INGLÉS","text":"En español puedes decir ''Soy estudiante'' sin el ''yo'' porque la terminación verbal indica el sujeto. En inglés el verbo no varía con el sujeto (excepto la -s de tercera persona), así que el pronombre es OBLIGATORIO para saber quién realiza la acción: ''Am a student'' es incorrecto — debe ser ''I am a student''. Esta es una de las reglas más importantes que diferencian el inglés del español."},{"type":"examples","title":"PRONOMBRES EN CONTEXTO","items":[{"label":"Sustitución","en":"My sister is a doctor. She works at a hospital. She loves her job.","es":"Mi hermana es doctora. Ella trabaja en un hospital. Le encanta su trabajo."},{"label":"IT para el tiempo","en":"It''s raining! It''s also very cold. It''s not a good day for a walk.","es":"¡Está lloviendo! También hace mucho frío. No es un buen día para caminar."},{"label":"THEY para cosas","en":"These shoes are beautiful. They are also very comfortable.","es":"Estos zapatos son hermosos. También son muy cómodos."},{"label":"YOU plural","en":"Hello everyone! You are all very welcome here today.","es":"¡Hola a todos! Todos ustedes son muy bienvenidos aquí hoy."}]},{"type":"note","variant":"tip","text":"I siempre se escribe con MAYÚSCULA en inglés, sin importar su posición en la oración. ''my friend and I went to the store'' (la I va en mayúscula). Esto es una convención ortográfica del inglés — no opcional."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0011-000000000002','00000001-0000-0000-0000-000000000011','00000000-0000-0000-0001-000000000001',2,'pronombres-objeto','{"es":"Pronombres Objeto","en":"Object Pronouns"}','{"es":"Aprende me, you, him, her, it, us, them — pronombres que van después del verbo o de una preposición.","en":"Learn me, you, him, her, it, us, them — pronouns that come after a verb or a preposition."}','theory_practice',20,15,'{"intro":"Los pronombres objeto se usan cuando el pronombre recibe la acción del verbo (objeto directo/indirecto) o cuando va después de una preposición. En español también tenemos esta distinción: yo/me, él/lo, etc. En inglés la diferencia es muy clara y sistemática.","sections":[{"type":"table","title":"PRONOMBRES SUJETO vs OBJETO","headers":["Sujeto","Objeto","Ejemplo sujeto","Ejemplo objeto"],"rows":[["I","me","I love chocolate.","She called me."],["you","you","You are great.","I like you."],["he","him","He is funny.","We invited him."],["she","her","She is smart.","I know her."],["it","it","It is broken.","I fixed it."],["we","us","We are ready.","They helped us."],["they","them","They are here.","I saw them."]]},{"type":"explanation","title":"CUÁNDO USAR EL PRONOMBRE OBJETO","text":"Usa el pronombre objeto cuando: (1) Es el objeto directo del verbo: ''She loves him'' (lo ama), ''I called her'' (la llamé), ''We need it'' (lo necesitamos). (2) Es el objeto indirecto: ''Give me the book'' (dame el libro), ''Tell us the answer'' (dínos la respuesta). (3) Va después de una preposición: ''This is for you'' (esto es para ti), ''She came with us'' (vino con nosotros), ''I''m talking about him'' (estoy hablando de él), ''The gift is from them'' (el regalo es de ellos)."},{"type":"examples","title":"EJEMPLOS EN CONTEXTO","items":[{"label":"Objeto directo","en":"I love her. She loves me too. We love each other.","es":"La amo. Ella también me ama. Nos amamos mutuamente."},{"label":"Después de preposición","en":"This book is for you. Can you come with me?","es":"Este libro es para ti. ¿Puedes venir conmigo?"},{"label":"Objeto indirecto","en":"Tell him the truth. Show us the photos.","es":"Dile la verdad. Muéstranos las fotos."},{"label":"Hablar DE alguien","en":"I was talking about them, not about you.","es":"Estaba hablando de ellos, no de ti."}]},{"type":"note","variant":"warning","text":"Error muy común: ''Between you and I'' (incorrecto) → ''Between you and me'' (correcto). Después de preposición siempre va el pronombre OBJETO: ''between me'', ''with her'', ''for us'', ''about them''. El error ''between you and I'' existe hasta en hablantes nativos pero es formalmente incorrecto."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0011-000000000003','00000001-0000-0000-0000-000000000011','00000000-0000-0000-0001-000000000001',3,'adjetivos-posesivos','{"es":"Adjetivos Posesivos","en":"Possessive Adjectives"}','{"es":"Aprende my, your, his, her, its, our, their — los adjetivos posesivos que van antes del sustantivo.","en":"Learn my, your, his, her, its, our, their — possessive adjectives that go before a noun."}','theory_practice',20,15,'{"intro":"Los adjetivos posesivos indican a quién pertenece algo. En inglés van siempre ANTES del sustantivo y no cambian por género ni número. ''Mi libro'', ''mi mesa'', ''mis libros'', ''mis mesas'' — todos se traducen con el mismo ''my''. Esto simplifica mucho la gramática comparado con el español.","sections":[{"type":"table","title":"ADJETIVOS POSESIVOS","headers":["Pronombre sujeto","Adjetivo posesivo","Equivalente español","Ejemplo"],"rows":[["I","my","mi / mis","My name is Carlos. This is my book."],["you","your","tu/sus (de usted)","What''s your name? Is this your car?"],["he","his","su (de él)","His name is David. That''s his phone."],["she","her","su (de ella)","Her name is Sofia. That''s her bag."],["it","its","su (de ello)","The cat licked its paw. Its name is Luna."],["we","our","nuestro/a/os/as","Our house is big. These are our children."],["they","their","su (de ellos)","Their names are Tom and Sara. That''s their car."]]},{"type":"explanation","title":"HIS vs HER — GÉNERO GRAMATICAL","text":"En inglés, HIS se usa para cosas que pertenecen a una persona MASCULINA (él), y HER para cosas que pertenecen a una persona FEMENINA (ella). El adjetivo posesivo concuerda con el POSEEDOR, no con la cosa poseída. Esto es diferente al español donde ''su'' es ambiguo: ''John lost his keys'' (John perdió sus llaves — his porque John es hombre), ''Maria lost her keys'' (Maria perdió sus llaves — her porque Maria es mujer). En español ambos serían ''sus llaves''."},{"type":"explanation","title":"ITS — CUIDADO CON EL APÓSTROFE","text":"ITS (sin apóstrofe) es el adjetivo posesivo de IT: ''The dog wagged its tail'' (el perro movió su cola). IT''S (con apóstrofe) siempre significa ''it is''. Esta confusión es uno de los errores ortográficos más comunes incluso para hablantes nativos. Regla: si puedes reemplazarlo por ''it is'', usa IT''S. Si indica posesión, usa ITS."},{"type":"examples","title":"POSESIVOS EN CONTEXTO","items":[{"label":"Presentación","en":"My name is Luis. This is my wife. Her name is Carmen.","es":"Mi nombre es Luis. Esta es mi esposa. Su nombre es Carmen."},{"label":"His vs her","en":"Tom has a dog. Its name is Rex. He loves his dog. His sister has a cat. Her cat is named Mia.","es":"Tom tiene un perro. Su nombre es Rex. Él ama a su perro. Su hermana tiene un gato. Su gato se llama Mía."},{"label":"Plural","en":"We have a new apartment. Our neighbors are very friendly.","es":"Tenemos un nuevo apartamento. Nuestros vecinos son muy amables."}]},{"type":"note","variant":"tip","text":"Para memorizar los posesivos: siguen exactamente el mismo orden que los pronombres sujeto. I→my, you→your, he→his, she→her, it→its, we→our, they→their. Si sabes los pronombres sujeto, solo necesitas aprender las formas posesivas correspondientes."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0011-000000000004','00000001-0000-0000-0000-000000000011','00000000-0000-0000-0001-000000000001',4,'pronombres-posesivos','{"es":"Pronombres Posesivos y Posesivo con ''s","en":"Possessive Pronouns and Possessive ''s"}','{"es":"Aprende mine, yours, his, hers, ours, theirs y cómo usar ''s para indicar posesión en inglés.","en":"Learn mine, yours, his, hers, ours, theirs and how to use ''s to show possession in English."}','theory_practice',20,15,'{"intro":"En esta lección aprendes dos formas relacionadas con la posesión: los pronombres posesivos (mine, yours, his, hers, ours, theirs) que reemplazan al sustantivo completo, y el posesivo con ''s que se añade a sustantivos para indicar pertenencia.","sections":[{"type":"table","title":"ADJETIVO POSESIVO vs PRONOMBRE POSESIVO","headers":["Adjetivo posesivo","Pronombre posesivo","Diferencia","Ejemplo"],"rows":[["my","mine","my + sustantivo / mine solo","This is my book. / This book is mine."],["your","yours","your + sustantivo / yours solo","Is this your pen? / Is this pen yours?"],["his","his","su / suyo (él) — igual en ambos","His car is fast. / That fast car is his."],["her","hers","su / suyo (ella)","Her bag is red. / That red bag is hers."],["its","its","No tiene pronombre posesivo común","(raro en uso)"],["our","ours","nuestro+sust. / nuestro solo","Our house. / The house is ours."],["their","theirs","su+sust.(ellos) / suyo(ellos)","Their idea. / The idea is theirs."]]},{"type":"explanation","title":"EL POSESIVO CON ''S","text":"Para indicar que algo pertenece a alguien, en inglés se añade ''S al nombre del poseedor. John''s car = el coche de John. Maria''s book = el libro de María. My sister''s phone = el teléfono de mi hermana. The cat''s toy = el juguete del gato. Para nombres que terminan en S, se puede añadir ''s o solo el apóstrofe: James''s house o James'' house. Para plurales que terminan en S, solo el apóstrofe: The students'' books (los libros de los estudiantes)."},{"type":"examples","title":"POSESIVOS EN USO REAL","items":[{"label":"Pronombre posesivo","en":"Is this your jacket? — No, it''s not mine. Mine is blue.","es":"¿Es tuya esta chaqueta? — No, no es mía. La mía es azul."},{"label":"Posesivo con ''s","en":"This is Sarah''s apartment. It''s much bigger than Carlos''s.","es":"Este es el apartamento de Sarah. Es mucho más grande que el de Carlos."},{"label":"Pregunta de posesión","en":"Whose phone is this? — It''s mine. / It''s David''s.","es":"¿De quién es este teléfono? — Es mío. / Es de David."},{"label":"Plural posesivo","en":"The students'' exam results are excellent this year.","es":"Los resultados de los exámenes de los estudiantes son excelentes este año."}]},{"type":"note","variant":"tip","text":"WHOSE? (¿De quién?) es la palabra interrogativa para preguntar sobre posesión. ''Whose is this?'' (¿De quién es esto?), ''Whose car is that?'' (¿De quién es ese coche?). No confundas con WHO''S (who is): ''Who''s there?'' (¿Quién está ahí?) vs ''Whose bag is this?'' (¿De quién es esta bolsa?)."}]}','true');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0001-000000000001','00000002-0000-0000-0011-000000000001',1,'multiple_choice','{"text":"''___ is raining. ___ is cold and wet outside.''"}','{"text":"It / It"}','["He / He","She / She","They / They"]','{"es":"IT se usa como sujeto impersonal para el clima. ''It is raining'' = está lloviendo. La H del weather (el tiempo) no tiene pronombre — siempre IT."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0002-000000000001','00000002-0000-0000-0011-000000000001',2,'multiple_choice','{"text":"¿Cuál es correcto? ''Mi hermana es maestra. ___ trabaja en una escuela primaria.''"}','{"text":"She"}','["He","It","They"]','{"es":"''Mi hermana'' es femenino → SHE. En inglés el pronombre concuerda con el género de la persona: she para femenino, he para masculino."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0003-000000000001','00000002-0000-0000-0011-000000000001',3,'multiple_choice','{"text":"¿Por qué es INCORRECTO decir ''Is a student'' en inglés?"}','{"text":"Porque el sujeto es obligatorio en inglés — debe ser ''He/She/I is/am a student''"}','["Porque ''is'' no se usa con student","Porque falta el artículo a/an","Porque student debe ir en plural"]','{"es":"En inglés el pronombre sujeto es OBLIGATORIO. En español podemos decir ''Es estudiante'' sin el ''él'' porque la conjugación verbal indica el sujeto. En inglés eso no es posible."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0004-000000000001','00000002-0000-0000-0011-000000000001',4,'multiple_choice','{"text":"''Maria and Carlos are my friends. ___ are very kind.''"}','{"text":"They"}','["He","She","We"]','{"es":"Para referirse a más de una persona usamos THEY (plural). Maria AND Carlos son dos personas = plural = THEY."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0005-000000000001','00000002-0000-0000-0011-000000000001',5,'fill_blank','{"text":"My phone is new. ___ is very fast. My parents are home. ___ are watching TV."}','{"text":"It / They","accepted":["It / They"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0006-000000000001','00000002-0000-0000-0011-000000000001',6,'fill_blank','{"text":"___ am a teacher and my husband is an engineer. ___ work together sometimes."}','{"text":"I / We","accepted":["I / We"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0007-000000000001','00000002-0000-0000-0011-000000000001',7,'translation','{"text":"Ella es mi jefa. Es muy inteligente y muy organizada. Nosotros la respetamos mucho."}','{"text":"She is my boss. She is very intelligent and very organized. We respect her a lot.","accepted":["She is my boss. She is very intelligent and very organized. We respect her a lot.","She''s my boss. She''s very intelligent and organized. We respect her a lot."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0001-0008-000000000001','00000002-0000-0000-0011-000000000001',8,'translation','{"text":"¿Qué hora es? Son las 3. Hace calor hoy."}','{"text":"What time is it? It''s 3 o''clock. It''s hot today.","accepted":["What time is it? It''s 3 o''clock. It''s hot today.","What time is it? It is 3. It is hot today."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0001-000000000001','00000002-0000-0000-0011-000000000002',1,'multiple_choice','{"text":"''I love my sister. I call ___ every day.''"}','{"text":"her"}','["she","hers","they"]','{"es":"Después del verbo ''call'' necesitamos el pronombre OBJETO. ''She'' es sujeto, ''her'' es objeto. ''I call her'' = la llamo."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0002-000000000001','00000002-0000-0000-0011-000000000002',2,'multiple_choice','{"text":"''This gift is from your parents. It''s for ___.''"}','{"text":"you"}','["your","yours","we"]','{"es":"Después de la preposición ''for'' necesitamos pronombre objeto: ''for you'' (para ti). ''Your'' es adjetivo posesivo, no pronombre objeto."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0003-000000000001','00000002-0000-0000-0011-000000000002',3,'multiple_choice','{"text":"¿Cuál es CORRECTO?"}','{"text":"Can you help us? We need you."}','["Can you help we? We need you.","Can you help us? We need your.","Can you help our? We need you."]','{"es":"Después del verbo ''help'' va pronombre objeto: US (no WE). Después del verbo ''need'' va pronombre objeto: YOU (correcto). WE y YOUR son formas sujeto y posesivo respectivamente."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0004-000000000001','00000002-0000-0000-0011-000000000002',4,'multiple_choice','{"text":"''I was talking about ___, not about ___.'' (ellos / ti)"}','{"text":"them / you"}','["they / your","their / you","they / yours"]','{"es":"Después de la preposición ''about'' van pronombres objeto: ''about them'' (de ellos), ''about you'' (de ti). THEY y YOUR son formas sujeto/posesivo, no objeto."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0005-000000000001','00000002-0000-0000-0011-000000000002',5,'fill_blank','{"text":"I like my professor. She explains everything clearly. I understand ___ very well. She helps ___ a lot."}','{"text":"her / me","accepted":["her / me"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0006-000000000001','00000002-0000-0000-0011-000000000002',6,'fill_blank','{"text":"My parents work hard. I admire ___ so much. They always support ___ in everything."}','{"text":"them / me","accepted":["them / me"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0007-000000000001','00000002-0000-0000-0011-000000000002',7,'translation','{"text":"Lo conozco bien. Él me llama todos los días. Hablamos de todo."}','{"text":"I know him well. He calls me every day. We talk about everything.","accepted":["I know him well. He calls me every day. We talk about everything."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0002-0008-000000000001','00000002-0000-0000-0011-000000000002',8,'translation','{"text":"Este paquete es para nosotros. ¿Puedes traérnoslo?"}','{"text":"This package is for us. Can you bring it to us?","accepted":["This package is for us. Can you bring it to us?","This package is for us. Can you bring us it?"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0001-000000000001','00000002-0000-0000-0011-000000000003',1,'multiple_choice','{"text":"''Carlos tiene una hermana. ___ hermana se llama Laura.''"}','{"text":"His"}','["Her","Its","Their"]','{"es":"HIS se usa para cosas que pertenecen a una persona MASCULINA. Carlos es hombre → HIS sister (su hermana — de él). HER sería para una mujer."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0002-000000000001','00000002-0000-0000-0011-000000000003',2,'multiple_choice','{"text":"''The dog is sleeping. ___ tail is wagging.''"}','{"text":"Its"}','["It''s","His","Their"]','{"es":"ITS (sin apóstrofe) es el adjetivo posesivo de IT — para animales y cosas. IT''S (con apóstrofe) = ''it is''. Aquí necesitamos posesivo: la cola del perro → Its tail."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0003-000000000001','00000002-0000-0000-0011-000000000003',3,'multiple_choice','{"text":"¿Cuál es CORRECTO para ''Nuestros hijos están en la escuela''?"}','{"text":"Our children are at school."}','["We children are at school.","Us children are at school.","Ours children are at school."]','{"es":"OUR es el adjetivo posesivo de WE: our children (nuestros hijos). WE y US son pronombres sujeto/objeto. OURS es pronombre posesivo (va solo, sin sustantivo)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0004-000000000001','00000002-0000-0000-0011-000000000003',4,'multiple_choice','{"text":"''What''s ___ name?'' — ''My name is Ana.''"}','{"text":"your"}','["you","yours","his"]','{"es":"YOUR es el adjetivo posesivo de YOU. ''What''s your name?'' = ¿Cuál es tu nombre? Es la pregunta de presentación más básica del inglés."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0005-000000000001','00000002-0000-0000-0011-000000000003',5,'fill_blank','{"text":"Maria has a brother. ___ brother is 20. He has a girlfriend. ___ girlfriend is from Spain."}','{"text":"Her / His","accepted":["Her / His"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0006-000000000001','00000002-0000-0000-0011-000000000003',6,'fill_blank','{"text":"I love ___ job. ___ colleagues are great and ___ boss is very supportive."}','{"text":"my / My / my","accepted":["my / My / my"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0007-000000000001','00000002-0000-0000-0011-000000000003',7,'translation','{"text":"Su nombre es Pedro. Su esposa se llama Ana. Su hijo tiene 5 años."}','{"text":"His name is Pedro. His wife''s name is Ana. Their son is 5 years old.","accepted":["His name is Pedro. His wife''s name is Ana. Their son is 5 years old.","His name is Pedro. His wife is called Ana. Their son is 5 years old."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0003-0008-000000000001','00000002-0000-0000-0011-000000000003',8,'translation','{"text":"Nuestro equipo es el mejor. Nuestro entrenador es fantástico y nuestras jugadoras son increíbles."}','{"text":"Our team is the best. Our coach is fantastic and our players are incredible.","accepted":["Our team is the best. Our coach is fantastic and our players are incredible."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0001-000000000001','00000002-0000-0000-0011-000000000004',1,'multiple_choice','{"text":"''Is this your car?'' — ''No, it''s not ___. Mine is the red one.''"}','{"text":"mine"}','["my","me","I''s"]','{"es":"MINE es el pronombre posesivo de I/MY. Va solo, sin sustantivo: ''It''s mine'' (es mío). MY necesita un sustantivo después: ''my car'' (mi coche)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0002-000000000001','00000002-0000-0000-0011-000000000004',2,'multiple_choice','{"text":"''Whose book is this?'' — ''It''s ___.'' (de ella)"}','{"text":"hers"}','["her","she''s","her''s"]','{"es":"HERS es el pronombre posesivo de SHE/HER. Nunca se escribe ''her''s'' con apóstrofe — el apóstrofe en posesivos solo se usa con sustantivos (Mary''s), no con pronombres."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0003-000000000001','00000002-0000-0000-0011-000000000004',3,'multiple_choice','{"text":"''These seats are ours.'' — ¿Qué significa?"}','{"text":"Estos asientos son nuestros."}','["Estos asientos son para nosotros.","Nosotros tenemos asientos.","Nuestros asientos están aquí."]','{"es":"OURS = nuestro/a/os/as (pronombre posesivo de WE/OUR). Va solo, sin sustantivo después: ''These seats are ours'' = ''Estos asientos son nuestros''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0004-000000000001','00000002-0000-0000-0011-000000000004',4,'multiple_choice','{"text":"¿Cómo se pregunta ''¿De quién es esto?'' en inglés?"}','{"text":"Whose is this?"}','["Who''s is this?","Who is this?","Whose this is?"]','{"es":"WHOSE (¿de quién?) es la palabra interrogativa para posesión. ''Whose is this?'' = ¿De quién es esto? No confundir con WHO''S (who is): ''Who''s there?'' ≠ ''Whose is this?''"}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0005-000000000001','00000002-0000-0000-0011-000000000004',5,'fill_blank','{"text":"I have my phone. Do you have ___? Tom has his laptop. Where''s ___?"}','{"text":"yours / his","accepted":["yours / his"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0006-000000000001','00000002-0000-0000-0011-000000000004',6,'fill_blank','{"text":"This is Tom''s umbrella. This one is ___ (de ella). And the blue one is ___ (de nosotros)."}','{"text":"hers / ours","accepted":["hers / ours"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0007-000000000001','00000002-0000-0000-0011-000000000004',7,'translation','{"text":"¿De quién es este abrigo? — Es mío. El tuyo está en el armario."}','{"text":"Whose coat is this? — It''s mine. Yours is in the closet.","accepted":["Whose coat is this? — It''s mine. Yours is in the closet.","Whose is this coat? — It''s mine. Yours is in the wardrobe."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0011-0004-0008-000000000001','00000002-0000-0000-0011-000000000004',8,'translation','{"text":"Ese coche es de David. El de María está en el garaje. El nuestro está en la calle."}','{"text":"That car is David''s. Maria''s is in the garage. Ours is on the street.","accepted":["That car is David''s. Maria''s is in the garage. Ours is on the street."]}',NULL,NULL);
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0012-000000000001','00000001-0000-0000-0000-000000000012','00000000-0000-0000-0001-000000000001',1,'frases-en-el-aula','{"es":"Frases Esenciales en el Aula","en":"Essential Classroom Phrases"}','{"es":"Aprende las frases más importantes para comunicarte en una clase de inglés: instrucciones, preguntas y respuestas comunes.","en":"Learn the most important phrases to communicate in an English class: instructions, questions, and common responses."}','theory_practice',20,15,'{"intro":"Para aprender inglés de manera eficaz, necesitas saber cómo comunicarte en un ambiente de aprendizaje. Estas frases de ''classroom language'' te permitirán participar activamente, pedir ayuda, confirmar que entendiste, y interactuar con el profesor y compañeros en inglés desde el primer día.","sections":[{"type":"table","title":"FRASES DEL PROFESOR","headers":["Inglés","Español"],"rows":[["Open your books to page 15.","Abran sus libros en la página 15."],["Listen carefully.","Escuchen con atención."],["Repeat after me.","Repitan después de mí."],["Work in pairs / in groups.","Trabajen en parejas / en grupos."],["What does this word mean?","¿Qué significa esta palabra?"],["Can anyone answer this question?","¿Puede alguien responder esta pregunta?"],["That''s correct! / Well done!","¡Correcto! / ¡Bien hecho!"],["Not quite. Try again.","No del todo. Inténtalo de nuevo."],["Time''s up!","¡Se acabó el tiempo!"],["Any questions?","¿Alguna pregunta?"]]},{"type":"table","title":"FRASES DEL ESTUDIANTE","headers":["Inglés","Español"],"rows":[["Can you repeat that, please?","¿Puede repetir eso, por favor?"],["Can you speak more slowly, please?","¿Puede hablar más despacio, por favor?"],["What does ''...'' mean?","¿Qué significa ''...''?"],["How do you say ''...'' in English?","¿Cómo se dice ''...'' en inglés?"],["How do you spell that?","¿Cómo se deletrea eso?"],["I don''t understand.","No entiendo."],["I''m not sure.","No estoy seguro/a."],["Can you give an example?","¿Puede dar un ejemplo?"],["Is this correct?","¿Es esto correcto?"],["I have a question.","Tengo una pregunta."]]},{"type":"explanation","title":"EXPRESIONES DE COMPRENSIÓN","text":"Para indicar que entendiste o no, usa estas expresiones: I understand (entiendo), I see (ya veo, entiendo), Got it! (¡Entendí! — informal), I''m following you (te estoy siguiendo/entiendo), I''m lost (me perdí/no entiendo), I''m confused (estoy confundido/a). Para pedir que alguien repita: Sorry? / Pardon? / Can you say that again? (¿Podría repetir eso?)."},{"type":"examples","title":"SITUACIONES EN CLASE","items":[{"label":"Pedir repetición","en":"Sorry, I didn''t catch that. Can you repeat it more slowly?","es":"Disculpe, no escuché bien. ¿Puede repetirlo más despacio?"},{"label":"Preguntar significado","en":"Excuse me, what does ''fluent'' mean?","es":"Disculpe, ¿qué significa ''fluent''?"},{"label":"Confirmar","en":"So, the answer is ''were'', is that right?","es":"Entonces, la respuesta es ''were'', ¿está bien?"},{"label":"No entender","en":"I''m a bit confused about the difference between ''since'' and ''for''.","es":"Estoy un poco confundido sobre la diferencia entre ''since'' y ''for''."}]},{"type":"note","variant":"tip","text":"El lenguaje del aula es tu primer entorno comunicativo real en inglés. Usar estas frases desde el primer día — incluso con errores — te ayudará a perder el miedo a hablar. Tu profesor siempre preferirá que intentes comunicarte en inglés antes que que te quedes callado."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0012-000000000002','00000001-0000-0000-0000-000000000012','00000000-0000-0000-0001-000000000001',2,'pedir-ayuda-aclaracion','{"es":"Pedir Ayuda y Aclaración","en":"Asking for Help and Clarification"}','{"es":"Aprende cómo pedir ayuda, aclarar dudas y verificar que entendiste en situaciones cotidianas.","en":"Learn how to ask for help, clarify doubts, and verify that you understood in everyday situations."}','theory_practice',20,15,'{"intro":"Pedir ayuda y aclarar dudas son habilidades comunicativas fundamentales. En inglés hay formas muy corteses y eficaces de hacerlo. Saber pedir ayuda correctamente te permite avanzar más rápido en tu aprendizaje y funcionar con mayor confianza en situaciones reales.","sections":[{"type":"table","title":"CÓMO PEDIR AYUDA","headers":["Frase en inglés","Español","Nivel de formalidad"],"rows":[["Excuse me, can you help me?","Disculpe, ¿me puede ayudar?","neutro"],["Could you help me, please?","¿Podría ayudarme, por favor?","formal/cortés"],["Do you mind helping me?","¿Le importaría ayudarme?","muy cortés"],["I need some help with...","Necesito ayuda con...","directo"],["Can I ask you something?","¿Le puedo preguntar algo?","neutro"],["Would you mind explaining...?","¿Le importaría explicar...?","formal"]]},{"type":"table","title":"CÓMO PEDIR ACLARACIÓN","headers":["Frase en inglés","Cuándo usarla"],"rows":[["Sorry, I didn''t understand.","No entendiste nada"],["I''m not sure I follow you.","Entendiste algo pero no completamente"],["Could you clarify that?","Quieres más detalles/claridad"],["What do you mean by...?","Una parte específica no quedó clara"],["Could you give an example?","Necesitas un ejemplo concreto"],["Let me make sure I understand...","Para verificar tu comprensión"]]},{"type":"explanation","title":"VERIFICAR COMPRENSIÓN","text":"Después de recibir una explicación, puedes verificar que entendiste con estas frases: ''So you mean that...?'' (O sea que quieres decir que...?), ''If I understand correctly, ...'' (Si entiendo correctamente, ...), ''Let me repeat to make sure: ...'' (Déjame repetir para confirmar: ...), ''Just to clarify, ...'' (Solo para aclarar, ...), ''Am I right that...?'' (¿Tengo razón en que...?)."},{"type":"examples","title":"DIÁLOGOS DE AYUDA REAL","items":[{"label":"En la calle","en":"Excuse me, could you help me? I''m lost. I''m looking for the train station.","es":"Disculpe, ¿podría ayudarme? Estoy perdido. Busco la estación de tren."},{"label":"En la oficina","en":"I''m not sure I follow. Could you explain the second step again?","es":"No estoy seguro de entender. ¿Podría explicar el segundo paso de nuevo?"},{"label":"Verificar","en":"So if I understand correctly, I need to submit the form before Friday, right?","es":"Entonces, si entiendo correctamente, necesito enviar el formulario antes del viernes, ¿verdad?"},{"label":"En clase","en":"Excuse me, what''s the difference between ''look'', ''see'', and ''watch''?","es":"Disculpe, ¿cuál es la diferencia entre ''look'', ''see'' y ''watch''?"}]},{"type":"note","variant":"tip","text":"Siempre di PLEASE cuando pides algo y THANK YOU cuando recibes ayuda. Estas dos palabras, usadas consistentemente, hacen toda la diferencia en cómo te perciben en inglés. Añade ''please'' al final o ''could you'' al principio para sonar más cortés automáticamente."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0012-000000000003','00000001-0000-0000-0000-000000000012','00000000-0000-0000-0001-000000000001',3,'expresar-acuerdo-desacuerdo','{"es":"Expresar Acuerdo y Desacuerdo","en":"Expressing Agreement and Disagreement"}','{"es":"Aprende a expresar que estás de acuerdo o en desacuerdo de manera cortés y natural en inglés.","en":"Learn to express agreement or disagreement in a polite and natural way in English."}','theory_practice',20,15,'{"intro":"Expresar opiniones, acuerdo y desacuerdo es una habilidad conversacional esencial. En inglés hay muchas formas de hacerlo con distintos niveles de intensidad y formalidad. Esta lección te da las herramientas para participar activamente en conversaciones y debates en inglés.","sections":[{"type":"table","title":"EXPRESAR ACUERDO","headers":["Inglés","Español","Intensidad"],"rows":[["I agree.","Estoy de acuerdo.","neutral"],["I totally agree.","Estoy totalmente de acuerdo.","fuerte"],["Exactly! / Absolutely!","¡Exactamente! / ¡Totalmente!","muy fuerte"],["You''re right.","Tienes razón.","neutral"],["That''s a good point.","Ese es un buen punto.","moderado"],["I think so too.","Yo también lo creo.","moderado"],["Me too. / So do I.","Yo también.","casual"]]},{"type":"table","title":"EXPRESAR DESACUERDO (CON CORTESÍA)","headers":["Inglés","Español","Nivel cortesía"],"rows":[["I don''t agree.","No estoy de acuerdo.","directo"],["I''m not sure about that.","No estoy seguro de eso.","suave"],["I see your point, but...","Entiendo tu punto, pero...","muy cortés"],["I''m afraid I disagree.","Me temo que no estoy de acuerdo.","formal/cortés"],["That''s not entirely true.","Eso no es del todo cierto.","moderado"],["Actually, I think...","En realidad, yo creo que...","suave/corrección"]]},{"type":"explanation","title":"EXPRESAR OPINIONES","text":"Para dar tu opinión en inglés: I think (creo/pienso), I believe (creo/considero — más formal), In my opinion (en mi opinión), I feel (siento/creo — más emocional), As far as I''m concerned (en lo que a mí respecta). Para indicar que es tu opinión personal y no un hecho: ''I think it''s too expensive'' (creo que es demasiado caro — no es un hecho, es mi opinión), ''In my opinion, this is the best option'' (en mi opinión, esta es la mejor opción)."},{"type":"examples","title":"CONVERSACIONES DE OPINIÓN","items":[{"label":"Acuerdo total","en":"A: This city is too crowded. B: I totally agree! It''s getting worse every year.","es":"A: Esta ciudad está muy llena. B: ¡Totalmente de acuerdo! Empeora cada año."},{"label":"Desacuerdo cortés","en":"A: I think remote work is better. B: I see your point, but I prefer working in an office.","es":"A: Creo que trabajar desde casa es mejor. B: Entiendo tu punto, pero yo prefiero trabajar en la oficina."},{"label":"Opinión personal","en":"In my opinion, learning English is essential for a good career today.","es":"En mi opinión, aprender inglés es esencial para una buena carrera hoy en día."},{"label":"Corrección suave","en":"Actually, I don''t think that''s correct. The meeting is on Thursday, not Friday.","es":"En realidad, no creo que eso sea correcto. La reunión es el jueves, no el viernes."}]},{"type":"note","variant":"tip","text":"Para desacuerdo SIEMPRE usa frases de cushion (amortiguadores) antes de la parte negativa: ''I see your point, but...'', ''I understand what you mean, however...'', ''That''s interesting, but I think...''. Desacuerdo directo sin amortiguador puede sonar grosero en inglés, especialmente en contextos formales."}]}','true');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('00000002-0000-0000-0012-000000000004','00000001-0000-0000-0000-000000000012','00000000-0000-0000-0001-000000000001',4,'repaso-general-a1','{"es":"Repaso General A1: ¡Lo Has Logrado!","en":"A1 General Review: You''ve Done It!"}','{"es":"Repaso completo de todo el contenido A1: pronunciación, vocabulario, gramática y frases funcionales. ¡Celebra tu progreso!","en":"Complete review of all A1 content: pronunciation, vocabulary, grammar, and functional phrases. Celebrate your progress!"}','theory_practice',30,25,'{"intro":"¡Felicitaciones! Has completado el nivel A1 de inglés. En esta lección repasaremos los puntos clave de todo lo que aprendiste. Completar el A1 significa que puedes presentarte, describir tu entorno, usar el verbo To Be con confianza, entender frases básicas y comunicarte en situaciones simples de la vida cotidiana. Eso es un logro real.","sections":[{"type":"explanation","title":"LO QUE APRENDISTE EN A1","text":"A lo largo de los 12 módulos del nivel A1 aprendiste: El alfabeto inglés y la pronunciación de las vocales y consonantes difíciles. Saludos y presentaciones formales e informales. Los números del 1 al 1000, los ordinales y los precios. Los días de la semana, los meses, las estaciones, las horas y las fechas. Vocabulario de colores y adjetivos descriptivos. La familia y las relaciones personales. Comida, bebida y restaurantes. Las partes del cuerpo. El verbo To Be en todas sus formas (afirmativa, negativa, interrogativa). El uso de artículos A/AN/THE. Plurales regulares e irregulares. Sustantivos contables e incontables. Los pronombres sujeto, objeto, adjetivos posesivos y pronombres posesivos. Lenguaje funcional del aula, petición de ayuda y expresión de opiniones."},{"type":"table","title":"RESUMEN GRAMATICAL A1","headers":["Estructura","Ejemplo","Nota"],"rows":[["To Be afirmativo","I''m a student. She''s happy.","am/is/are + contracciones"],["To Be negativo","He isn''t here. We aren''t tired.","isn''t / aren''t / I''m not"],["To Be interrogativo","Is she a doctor? Where are you from?","Inversión verbo-sujeto"],["A/AN","a book, an apple, a university","Según SONIDO, no letra"],["THE","The sun, the best, the door","Específico, único, superlativo"],["Plurales","books, cities, children, people","Regular + irregulares"],["Pronombres sujeto","I, you, he, she, it, we, they","Obligatorios en inglés"],["Adjetivos posesivos","my, your, his, her, its, our, their","Antes del sustantivo"],["Pronombres posesivos","mine, yours, his, hers, ours, theirs","Solos, sin sustantivo"],["Sensaciones físicas","I''m hungry/cold/thirsty","TO BE, no HAVE"]]},{"type":"explanation","title":"TU NIVEL REAL AHORA","text":"Al completar el A1 puedes: Presentarte y presentar a otros en inglés. Hablar sobre tu familia, tu trabajo y tu ciudad. Describir personas, objetos y lugares con adjetivos. Preguntar y responder sobre la identidad, origen y profesión. Entender instrucciones simples y señales en inglés. Usar vocabulario de situaciones cotidianas: comida, números, tiempo, familia. Pedir ayuda y aclaración de manera cortés. Estos son los cimientos sobre los que se construye todo el inglés que aprenderás en los niveles A2, B1 y más allá."},{"type":"examples","title":"LO QUE PUEDES DECIR AHORA","items":[{"label":"Presentación completa","en":"Hi! I''m Carlos. I''m 28 years old and I''m from Guadalajara, Mexico. I''m a software engineer. I''m married and I have two children.","es":"¡Hola! Soy Carlos. Tengo 28 años y soy de Guadalajara, México. Soy ingeniero de software. Estoy casado y tengo dos hijos."},{"label":"Descripción","en":"My sister is tall and thin. She has brown eyes. She''s very smart and funny. She''s a lawyer.","es":"Mi hermana es alta y delgada. Tiene ojos marrones. Es muy inteligente y graciosa. Es abogada."},{"label":"Situación cotidiana","en":"Excuse me, is there a pharmacy near here? — Yes, there''s one on Main Street. It''s about 5 minutes on foot.","es":"Disculpe, ¿hay una farmacia cerca? — Sí, hay una en la calle principal. Son unos 5 minutos a pie."}]},{"type":"note","variant":"tip","text":"¡El aprendizaje de idiomas es un maratón, no un sprint! La clave es la consistencia: 20-30 minutos diarios de práctica son más efectivos que 3 horas un día a la semana. En el nivel A2 aprenderás los tiempos verbales pasados, el presente continuo, y mucho vocabulario nuevo. ¡Sigue adelante!"}]}','true');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0001-000000000001','00000002-0000-0000-0012-000000000001',1,'flashcard','{"text":"Can you repeat that, please?","subtext":"Frase esencial para el aula"}','{"text":"¿Puede repetir eso, por favor?","phonetic":"/kæn juː rɪˈpiːt ðæt pliːz/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0002-000000000001','00000002-0000-0000-0012-000000000001',2,'flashcard','{"text":"I don''t understand.","subtext":"Cómo decir que no entiendes"}','{"text":"No entiendo.","phonetic":"/aɪ doʊnt ˌʌndərˈstænd/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0003-000000000001','00000002-0000-0000-0012-000000000001',3,'multiple_choice','{"text":"El profesor dice: ''That''s correct! Well done!'' ¿Qué significa?"}','{"text":"¡Correcto! ¡Bien hecho!"}','["Incorrecto, inténtalo de nuevo.","Es una pregunta.","¡Se acabó el tiempo!"]','{"es":"''That''s correct'' = eso es correcto. ''Well done!'' = ¡bien hecho! Son frases de elogio que el profesor usa cuando das una respuesta correcta."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0004-000000000001','00000002-0000-0000-0012-000000000001',4,'multiple_choice','{"text":"Quieres preguntar el significado de la palabra ''fluent''. ¿Qué dices?"}','{"text":"Excuse me, what does ''fluent'' mean?"}','["Excuse me, how is ''fluent''?","Excuse me, what is the mean of ''fluent''?","Excuse me, what means ''fluent''?"]','{"es":"La estructura correcta para preguntar el significado es: ''What does X mean?'' El error común es ''What means X?'' (incorrecto en inglés — los verbos auxiliares van primero en las preguntas)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0005-000000000001','00000002-0000-0000-0012-000000000001',5,'multiple_choice','{"text":"El profesor dice: ''Work in pairs.'' ¿Qué haces?"}','{"text":"Trabajas con un compañero (de dos en dos)"}','["Trabajas solo","Trabajas en grupos de tres","Trabajas en toda la clase"]','{"es":"''Work in pairs'' = trabajar en parejas (grupos de 2). ''Work in groups'' = trabajar en grupos (más de 2). ''Work individually/alone'' = trabajar solo."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0006-000000000001','00000002-0000-0000-0012-000000000001',6,'fill_blank','{"text":"No entendiste algo: ''I''m ___ confused. Could you ___ that again, more slowly?''"}','{"text":"a bit / repeat","accepted":["a bit / repeat"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0007-000000000001','00000002-0000-0000-0012-000000000001',7,'translation','{"text":"¿Cómo se dice ''cuaderno'' en inglés? ¿Puede dar un ejemplo?"}','{"text":"How do you say ''cuaderno'' in English? Can you give an example?","accepted":["How do you say ''cuaderno'' in English? Can you give an example?","How do you say ''cuaderno'' in English? Could you give an example?"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0001-0008-000000000001','00000002-0000-0000-0012-000000000001',8,'translation','{"text":"Disculpe, ¿puede hablar más despacio, por favor? No entendí la última parte."}','{"text":"Excuse me, can you speak more slowly, please? I didn''t understand the last part.","accepted":["Excuse me, can you speak more slowly, please? I didn''t understand the last part.","Excuse me, could you speak more slowly, please? I didn''t catch the last part."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0001-000000000001','00000002-0000-0000-0012-000000000002',1,'flashcard','{"text":"Could you help me, please?","subtext":"Forma cortés de pedir ayuda"}','{"text":"¿Podría ayudarme, por favor?","phonetic":"/kʊd juː hɛlp miː pliːz/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0002-000000000001','00000002-0000-0000-0012-000000000002',2,'multiple_choice','{"text":"¿Cuál es la forma MÁS CORTÉS de pedir ayuda?"}','{"text":"Would you mind helping me?"}','["Help me!","I want help.","Give me help."]','{"es":"''Would you mind...?'' es la forma más cortés y formal de pedir algo en inglés. ''Help me!'' suena como una orden. ''I want help'' es muy directo. En contextos formales siempre usa formas como ''Could you...?'' o ''Would you mind...?''"}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0003-000000000001','00000002-0000-0000-0012-000000000002',3,'multiple_choice','{"text":"Alguien te explicó algo y quieres verificar: ''So if I understand correctly, the deadline is next Monday?'' ¿Qué estás haciendo?"}','{"text":"Verificando tu comprensión repitiendo lo que entendiste"}','["Haciendo una pregunta nueva","Expresando desacuerdo","Pidiendo que lo repitan desde el principio"]','{"es":"''So if I understand correctly...'' es una frase para verificar comprensión: repites con tus propias palabras lo que entendiste para confirmar que es correcto. Es una técnica muy eficaz de comunicación."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0004-000000000001','00000002-0000-0000-0012-000000000002',4,'multiple_choice','{"text":"¿Cuál es la diferencia entre ''Excuse me'' y ''Sorry''?"}','{"text":"''Excuse me'' interrumpe o llama atención; ''Sorry'' pide disculpas por algo hecho"}','["Son exactamente lo mismo","''Excuse me'' es más informal","''Sorry'' se usa para interrumpir"]','{"es":"EXCUSE ME se usa para interrumpir, llamar la atención, o pasar por un lugar (¡Perdón, me permite!). SORRY se usa para disculparse por algo que hiciste: ''Sorry, I was late.'' En el aula usas EXCUSE ME para llamar al profesor."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0005-000000000001','00000002-0000-0000-0012-000000000002',5,'fill_blank','{"text":"I''m lost. ___ me, could you ___ me? I''m looking for the Central Museum."}','{"text":"Excuse / help","accepted":["Excuse / help"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0006-000000000001','00000002-0000-0000-0012-000000000002',6,'fill_blank','{"text":"I''m not sure I ___. Could you ___ that? I want to make sure I understand."}','{"text":"follow / clarify","accepted":["follow / clarify"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0007-000000000001','00000002-0000-0000-0012-000000000002',7,'translation','{"text":"¿Podría explicarme la diferencia entre estos dos documentos?"}','{"text":"Could you explain the difference between these two documents?","accepted":["Could you explain the difference between these two documents?","Would you mind explaining the difference between these two documents?"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0002-0008-000000000001','00000002-0000-0000-0012-000000000002',8,'translation','{"text":"Entonces, si entendí bien, necesito firmar aquí y enviar el formulario antes del viernes. ¿Es correcto?"}','{"text":"So if I understand correctly, I need to sign here and send the form before Friday. Is that right?","accepted":["So if I understand correctly, I need to sign here and send the form before Friday. Is that right?","So if I''m right, I need to sign here and submit the form by Friday. Correct?"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0001-000000000001','00000002-0000-0000-0012-000000000003',1,'flashcard','{"text":"I see your point, but...","subtext":"Forma cortés de introducir un desacuerdo"}','{"text":"Entiendo tu punto, pero... (desacuerdo cortés)","phonetic":"/aɪ siː jɔːr pɔɪnt bʌt/"}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0002-000000000001','00000002-0000-0000-0012-000000000003',2,'multiple_choice','{"text":"Tu amigo dice: ''This movie is terrible!'' Tú estás de acuerdo. ¿Qué dices?"}','{"text":"I totally agree! It''s really bad."}','["I don''t agree. It''s great!","I''m not sure.","That''s interesting."]','{"es":"''I totally agree'' expresa acuerdo fuerte. Para acuerdo más moderado: ''I agree'', ''You''re right'', ''I think so too''. Para desacuerdo: ''I don''t agree'', ''I''m not sure'', ''I see your point, but...''."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0003-000000000001','00000002-0000-0000-0012-000000000003',3,'multiple_choice','{"text":"Quieres expresar tu opinión personal sobre algo. ¿Cuál es la mejor forma?"}','{"text":"In my opinion, this is the best solution."}','["This is definitely the best solution.","Everyone knows this is the best solution.","It''s a fact that this is the best solution."]','{"es":"''In my opinion'' claramente indica que es tu opinión, no un hecho. Otras opciones: ''I think'', ''I believe'', ''I feel''. Usar estas frases es importante para distinguir opiniones de hechos."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0004-000000000001','00000002-0000-0000-0012-000000000003',4,'multiple_choice','{"text":"¿Cuál de estas es la forma más CORTÉS de expresar desacuerdo?"}','{"text":"I see your point, but I think there might be another way to look at this."}','["You''re wrong.","No, that''s not right.","I disagree completely."]','{"es":"En inglés, especialmente en contextos profesionales, el desacuerdo se expresa de forma muy indirecta y cortés. Las formas como ''you''re wrong'' suenan agresivas. Siempre reconoce primero la perspectiva del otro antes de contradecir."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0005-000000000001','00000002-0000-0000-0012-000000000003',5,'fill_blank','{"text":"A: Learning a language is easy. B: I ___ sure about that. I ___ it takes a lot of time and effort."}','{"text":"''m not / think","accepted":["''m not / think"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0006-000000000001','00000002-0000-0000-0012-000000000003',6,'fill_blank','{"text":"I ___ with you completely. That''s an excellent point. ___ my opinion, it''s the right decision."}','{"text":"agree / In","accepted":["agree / In"]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0007-000000000001','00000002-0000-0000-0012-000000000003',7,'translation','{"text":"Entiendo tu punto, pero en mi opinión, esta opción es demasiado cara."}','{"text":"I see your point, but in my opinion, this option is too expensive.","accepted":["I see your point, but in my opinion, this option is too expensive.","I understand your point, but I think this option is too expensive."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0003-0008-000000000001','00000002-0000-0000-0012-000000000003',8,'translation','{"text":"Estoy totalmente de acuerdo. Ese es un punto muy bueno. Yo también lo creo."}','{"text":"I totally agree. That''s a very good point. I think so too.","accepted":["I totally agree. That''s a very good point. I think so too.","I completely agree. That''s a great point. I think so too."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0001-000000000001','00000002-0000-0000-0012-000000000004',1,'multiple_choice','{"text":"Repaso: ¿Cuál oración es CORRECTA?"}','{"text":"She is an architect and her name is Laura."}','["She is a architect and her name is Laura.","She is an architect and hers name is Laura.","She are an architect and her name is Laura."]','{"es":"''Architect'' empieza con vocal → AN. Adjetivo posesivo antes de sustantivo → HER (no hers). Con she → IS (no are)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0002-000000000001','00000002-0000-0000-0012-000000000004',2,'multiple_choice','{"text":"Repaso: ¿Cómo se dice ''Tengo hambre y sed'' en inglés?"}','{"text":"I''m hungry and thirsty."}','["I have hungry and thirsty.","I am hungry and have thirsty.","I''m hunger and thirst."]','{"es":"Sensaciones físicas en inglés: TO BE + adjetivo. ''hungry'' (hambriento) y ''thirsty'' (sediento) son adjetivos. NUNCA ''I have hungry'' — es el error más común de hispanohablantes."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0003-000000000001','00000002-0000-0000-0012-000000000004',3,'multiple_choice','{"text":"Repaso: ''There are ___ children in the park. Two ___ and one ___.''"}','{"text":"three / girls / boy"}','["three / girles / boy","three / girls / boys","three / girl / boys"]','{"es":"''Girls'' = plural regular de girl. ''Boy'' aquí es singular (one = uno). Repaso de plurales: girl→girls (regular), boy→boys (regular con vocal+y)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0004-000000000001','00000002-0000-0000-0012-000000000004',4,'multiple_choice','{"text":"Repaso: ¿Cuál es la pregunta correcta para ''¿Cuántos años tienes?''"}','{"text":"How old are you?"}','["How many years do you have?","How years are you?","What is your age?"]','{"es":"La pregunta de edad en inglés siempre es ''How old are you?'' Nunca ''How many years do you have?'' — esa es la traducción literal del español. ''What is your age?'' existe pero es muy formal y poco natural."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0005-000000000001','00000002-0000-0000-0012-000000000004',5,'multiple_choice','{"text":"Repaso: ''___ sun rises in the east and sets in the west.''"}','{"text":"The"}','["A","An","(sin artículo)"]','{"es":"''The sun'' lleva THE porque el sol es único. Todo lo que es único en su especie lleva THE: the sun, the moon, the earth, the sky, the internet."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0006-000000000001','00000002-0000-0000-0012-000000000004',6,'fill_blank','{"text":"___ name is Pedro. I''m talking about ___, not about you. This bag is ___ — you can keep yours."}','{"text":"My / him / mine","accepted":["My / him / mine"]}',NULL,'{"es":"MY = adjetivo posesivo (antes de sustantivo). HIM = pronombre objeto (después de preposición ''about''). MINE = pronombre posesivo (solo, sin sustantivo después)."}');
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0007-000000000001','00000002-0000-0000-0012-000000000004',7,'translation','{"text":"Hola, me llamo Ana. Tengo 25 años y soy de México. Soy diseñadora gráfica. Encantada de conocerte."}','{"text":"Hi, my name is Ana. I''m 25 years old and I''m from Mexico. I''m a graphic designer. Nice to meet you.","accepted":["Hi, my name is Ana. I''m 25 years old and I''m from Mexico. I''m a graphic designer. Nice to meet you.","Hello, my name is Ana. I am 25 and I am from Mexico. I am a graphic designer. It''s nice to meet you."]}',NULL,NULL);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation) VALUES
('00000003-0012-0004-0008-000000000001','00000002-0000-0000-0012-000000000004',8,'translation','{"text":"Mi familia es grande. Somos cinco: mis padres, mis dos hermanos y yo. Ellos son muy importantes para mí."}','{"text":"My family is big. There are five of us: my parents, my two brothers, and me. They are very important to me.","accepted":["My family is big. There are five of us: my parents, my two brothers, and me. They are very important to me.","My family is large. We are five: my parents, my two brothers and I. They''re very important to me."]}',NULL,NULL);
